/* ACERCA · aplicación funcional */
const LEAVE_TYPES=['Hospitalización','Mudanza','Fallecimiento','Paternidad / maternidad','Deber inexcusable','Matrimonio propio','Matrimonio de terceros','Fuerza mayor','Horas médicas','Juicio','Ausencia justificada no retribuida','Ausencia injustificada','Baja médica'];
const persistedWorkerStatus=(()=>{try{const value=localStorage.getItem('acerca-worker-status');return ['all','active','inactive'].includes(value)?value:'all';}catch{return'all';}})();
const state={page:'inicio',workers:[],societies:[],vacations:[],leaves:[],incidents:[],partners:[],hours:[],payments:[],obligations:[],pending:[],bonusRecoveries:[],filters:{},analysis:{},workerStatus:persistedWorkerStatus,vacationWorkerId:'',vacationShowAll:false,vacationImportRows:[],calendarYear:new Date().getFullYear(),calendarMonth:new Date().getMonth()};
const titles={inicio:'Inicio',trabajadores:'Trabajadores',vacaciones:'Vacaciones',permisos:'Permisos y ausencias',incidencias:'Impuntualidades y abandonos',partners:'Partners',horas:'Horas extra',pagos:'Pagos adicionales',pendientes:'Pagos pendientes',bonos:'Bonos de asistencia',analisis:'Análisis',configuracion:'Configuración'};
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const isoDate=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
const calendarDayIndex=date=>Math.floor(Date.parse(date+'T00:00:00Z')/86400000);
const calendarDaysBetween=(start,end)=>calendarDayIndex(end)-calendarDayIndex(start)+1;
const today=()=>isoDate(new Date());
const money=v=>Number(v||0).toLocaleString('es-ES',{style:'currency',currency:'EUR'});
const fmt=d=>d?new Date(d+'T12:00:00').toLocaleDateString('es-ES'):'-';
const client=()=>window.ACERCA_SUPABASE;
function toast(m){const e=$('toast');e.textContent=m;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),3200);}
function modal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').classList.add('show');}
function closeModal(){$('modal').classList.remove('show');}
function norm(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');}
function normalizeCompany(s){const n=norm(s);return (state.societies||[]).find(x=>norm(x.name)===n)?.name||null;}
function workerName(id){const w=state.workers.find(x=>x.id===id);return w?w.agent:'Trabajador eliminado';}
function visibleWorkers(){return state.workers.filter(w=>state.workerStatus==='all'||(state.workerStatus==='active'?(!w.termination_date||w.termination_date>=today()):Boolean(w.termination_date&&w.termination_date<today())));}
function workerVisible(id){const worker=state.workers.find(w=>w.id===id);return !!worker&&visibleWorkers().some(w=>w.id===worker.id);}
function setWorkerStatus(value){state.workerStatus=['all','active','inactive'].includes(value)?value:'all';try{localStorage.setItem('acerca-worker-status',state.workerStatus);}catch{}render();}
function workerStatusControl(){return '<label class="worker-status-filter">Plantilla <select aria-label="Filtrar trabajadores por situación" onchange="setWorkerStatus(this.value)"><option value="all" '+(state.workerStatus==='all'?'selected':'')+'>Todos</option><option value="active" '+(state.workerStatus==='active'?'selected':'')+'>Solo activos</option><option value="inactive" '+(state.workerStatus==='inactive'?'selected':'')+'>Solo dados de baja</option></select></label>';}
function workerSearchField(label,name,selected=null){const selectedWorker=typeof selected==='string'?state.workers.find(w=>w.id===selected):selected,labelText=selectedWorker?selectedWorker.agent+' · '+selectedWorker.company:'';return '<div class="field worker-search-field"><label for="'+name+'_search">'+label+'</label><input id="'+name+'_search" type="search" autocomplete="off" placeholder="Escribe un nombre…" value="'+esc(labelText)+'" data-selected-label="'+esc(labelText)+'" data-worker-search="'+name+'" aria-controls="'+name+'_suggestions"><input id="'+name+'" name="'+name+'" type="hidden" value="'+esc(selectedWorker?.id||'')+'"><div class="worker-suggestions" id="'+name+'_suggestions" role="listbox" hidden></div></div>';}
function renderWorkerSuggestions(input){const field=input.dataset.workerSearch,list=$(field+'_suggestions'),query=norm(input.value.trim());if(!query){list.hidden=true;list.innerHTML='';return;}const matches=visibleWorkers().filter(w=>norm(w.agent+' '+w.company).includes(query)).slice(0,12);list.innerHTML=matches.length?matches.map(w=>'<button type="button" class="worker-suggestion" role="option" data-worker-field="'+esc(field)+'" data-worker-id="'+esc(w.id)+'" data-worker-label="'+esc(w.agent+' · '+w.company)+'"><b>'+esc(w.agent)+'</b><small>'+esc(w.company)+'</small></button>').join(''):'<div class="worker-no-match">No se encontraron trabajadores.</div>';list.hidden=false;}
const iconPaths={home:'<rect x="3" y="3" width="8" height="8" rx="1.5"/><rect x="13" y="3" width="8" height="5" rx="1.5"/><rect x="13" y="10" width="8" height="11" rx="1.5"/><rect x="3" y="13" width="8" height="8" rx="1.5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="10" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',handshake:'<path d="m11 17 2 2a2 2 0 0 0 3-3"/><path d="m14 14 4 4a2 2 0 0 0 3-3l-7-7-4 1-3-2-5 5a2 2 0 0 0 3 3l3-3"/><path d="m2 12 3 3m12-2 3-3M7 7l3-3 4 1 3-1 4 4"/>',coins:'<circle cx="8" cy="8" r="6"/><path d="M18.09 10.37A6 6 0 1 1 10.34 18M8 6v4l2 1m8-2v8m-4-4h8"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.7a8 8 0 0 1-1.7 1l-.3 1.8h-2.8l-.3-1.8a8 8 0 0 1-1.7-1l-1.7.7-1.4-2.4L7.3 15a8 8 0 0 1 0-2l-1.4-1.1 1.4-2.4 1.7.7a8 8 0 0 1 1.7-1l.3-1.8h2.8l.3 1.8a8 8 0 0 1 1.7 1l1.7-.7 1.4 2.4L19.4 13a8 8 0 0 1 0 2Z"/>',download:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 10l5 5 5-5M12 15V3"/>',plus:'<path d="M12 5v14M5 12h14"/>',edit:'<path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L9 17l-4 1 1-4Z"/>',check:'<path d="m5 12 4 4L19 6"/>'};
function icon(name,cls=''){return '<svg class="'+cls+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(iconPaths[name]||iconPaths.file)+'</svg>';}
function field(label,name,type='text',required=true,extra=''){return '<div class="field"><label for="'+name+'">'+label+'</label><input id="'+name+'" name="'+name+'" type="'+type+'" '+(required?'required':'')+' '+extra+'></div>';}
function selectField(label,name,options,required=true){return '<div class="field"><label for="'+name+'">'+label+'</label><select id="'+name+'" name="'+name+'" '+(required?'required':'')+'>'+options+'</select></div>';}
function textarea(label,name){return '<div class="field"><label for="'+name+'">'+label+(name==='notes'?' (opcional)':'')+'</label><textarea id="'+name+'" name="'+name+'" rows="3" '+(name==='notes'?'placeholder="Añade contexto o detalles del permiso…"':'')+'></textarea></div>';}
function checkbox(label,name,checked=false){return '<div class="field"><label style="display:flex;gap:8px;align-items:center"><input style="width:auto" type="checkbox" id="'+name+'" '+(checked?'checked':'')+'> '+label+'</label></div>';}
function formWrap(title,body,submit,handler){modal(title,'<form id="recordForm" onsubmit="'+handler+'(event)">'+body+'<div id="formStatus" class="notice">Los datos se guardarán en Supabase.</div><div class="actions" style="justify-content:flex-end"><button class="btn primary" id="saveBtn" type="submit">'+submit+'</button></div></form>');}
async function insert(table,row){const {data,error}=await client().from(table).insert(row).select().single();if(error)throw error;return data;}
async function update(table,id,patch){const {error}=await client().from(table).update(patch).eq('id',id);if(error)throw error;}
async function remove(table,id){const prompt=table==='vacation_records'?'¿Eliminar este periodo de vacaciones? Esta acción no se puede deshacer.':'¿Seguro que quieres eliminar este registro?';if(!confirm(prompt))return;const {error}=await client().from(table).delete().eq('id',id);if(error){toast(error.message);return;}if(table==='vacation_records')closeModal();await loadAll();toast(table==='vacation_records'?'Periodo de vacaciones eliminado.':'Registro eliminado.');}
async function deleteVacationRecord(id,view,value){if(!confirm('¿Eliminar este periodo de vacaciones? Esta acción no se puede deshacer.'))return;const {error}=await client().from('vacation_records').delete().eq('id',id);if(error){toast(error.message);return;}await loadAll();if(view==='history')showVacationHistory(value);else if(view==='calendar')calendarDay(value);toast('Periodo de vacaciones eliminado.');}
async function loadAll(){
 const db=client();if(!db)return;
  const specs=[['workers','workers','agent'],['societies','societies','name'],['vacation_records','vacations','start_date'],['leave_records','leaves','start_date'],['incident_records','incidents','incident_date'],['partner_records','partners','incorporation_date'],['extra_hours','hours','work_date'],['additional_payments','payments','payment_date'],['additional_payment_obligations','obligations','payroll_month'],['pending_payments','pending','expected_date'],['bonus_recoveries','bonusRecoveries','bonus_year']];
 const errors=[];
 await Promise.all(specs.map(async([table,key,sort])=>{const {data,error}=await db.from(table).select('*').order(sort,{ascending:false});if(error){state[key]=[];errors.push(table+': '+error.message);}else state[key]=data||[];}));
 if(errors.length)console.warn('Tablas pendientes de configurar:',errors);
 if(!errors.some(x=>x.startsWith('additional_payment_obligations:'))){try{await syncPaymentObligations();}catch(error){console.error('No se han podido actualizar los pagos previstos:',error);}}
 render();
 if(errors.length)toast('No se han podido cargar algunos módulos. Comprueba que has ejecutado supabase/acerca-modules.sql en Supabase.');
}
function firstFullPayrollMonth(worker){if(!worker?.hire_date)return null;const hire=new Date(worker.hire_date+'T12:00:00');if(Number.isNaN(hire.getTime()))return null;const month=new Date(hire.getFullYear(),hire.getMonth(),1);if(hire.getDate()>1)month.setMonth(month.getMonth()+1);const start=isoDate(month),end=isoDate(new Date(month.getFullYear(),month.getMonth()+1,0));if(worker.termination_date&&worker.termination_date<end)return null;return start;}
async function syncPaymentObligations(){
 const db=client(),{data:existing,error}=await db.from('additional_payment_obligations').select('*');
 if(error)throw error;
 const current=existing||[],byId=new Map(state.workers.map(w=>[w.id,w])),partnerById=new Map(state.partners.map(p=>[p.id,p])),candidates=[];
 for(const obligation of current){const partner=obligation.partner_record_id?partnerById.get(obligation.partner_record_id):null;if(partner?.employee_worker_id&&obligation.worker_id!==partner.employee_worker_id){const {error:updateError}=await db.from('additional_payment_obligations').update({worker_id:partner.employee_worker_id}).eq('id',obligation.id);if(updateError)throw updateError;obligation.worker_id=partner.employee_worker_id;}}
 for(const w of state.workers){const month=firstFullPayrollMonth(w);if(month&&!current.some(x=>x.obligation_type==='Formación'&&x.worker_id===w.id))candidates.push({worker_id:w.id,obligation_type:'Formación',payroll_month:month,amount:null,notes:'Pago de formación correspondiente a la primera nómina mensual completa.'});}
 for(const p of [...state.partners].sort((a,b)=>a.incorporation_date.localeCompare(b.incorporation_date))){const referred=byId.get(p.referred_worker_id),month=firstFullPayrollMonth(referred);if(month&&p.employee_worker_id&&p.status!=='Cancelado'&&p.status!=='Abonado'&&!current.some(x=>x.obligation_type==='Incentivo Partner'&&x.partner_record_id===p.id))candidates.push({worker_id:p.employee_worker_id,partner_record_id:p.id,obligation_type:'Incentivo Partner',payroll_month:month,amount:100,notes:'Incentivo de 100 € para el empleado referente cuando la persona referida completa su primer mes de nómina.'});}
 const stale=current.filter(x=>x.status!=='Abonado'&&x.status!=='No corresponde').filter(x=>{const partner=x.partner_record_id?partnerById.get(x.partner_record_id):null,eligibilityWorker=partner?byId.get(partner.referred_worker_id):byId.get(x.worker_id);return !eligibilityWorker||firstFullPayrollMonth(eligibilityWorker)!==x.payroll_month||(x.obligation_type==='Incentivo Partner'&&(!partner||partner.status==='Cancelado'));});
 if(stale.length){const {error:cancelError}=await db.from('additional_payment_obligations').update({status:'No corresponde'}).in('id',stale.map(x=>x.id));if(cancelError)throw cancelError;}
 if(candidates.length){const {error:insertError}=await db.from('additional_payment_obligations').insert(candidates);if(insertError&&insertError.code!=='23505')throw insertError;}
 const {data:latest,error:reloadError}=await db.from('additional_payment_obligations').select('*').order('payroll_month',{ascending:false});if(reloadError)throw reloadError;state.obligations=latest||[];
}
function dateFilter(key){const f=state.filters[key]||{};return '<form class="toolbar range" onsubmit="applyFilter(event,\''+key+'\')"><label>Desde<input id="from-'+key+'" type="date" value="'+(f.from||isoDate(new Date(new Date().getFullYear(),new Date().getMonth(),1)))+'"></label><label>Hasta<input id="to-'+key+'" type="date" value="'+(f.to||today())+'"></label><button class="btn">Aplicar filtro</button><button class="btn" type="button" onclick="resetFilter(\''+key+'\')">Restablecer</button></form>';}
function applyFilter(e,k){e.preventDefault();const from=$('from-'+k).value,to=$('to-'+k).value;if(from&&to&&from>to){toast('La fecha inicial no puede ser posterior a la final.');return;}state.filters[k]={from,to};render();}
function resetFilter(k){delete state.filters[k];render();}
function inRange(date,key){const f=state.filters[key];return !f||(!f.from||date>=f.from)&&(!f.to||date<=f.to);}
function overlapsRange(start,end,key){const f=state.filters[key];return !f||(!f.from||end>=f.from)&&(!f.to||start<=f.to);}
function monthInRange(month,key){if(!month)return false;const f=state.filters[key]||{},start=month.slice(0,7)+'-01',end=obligationMonthEnd(month);return (!f.from||end>=f.from)&&(!f.to||start<=f.to);}
function table(headers,rows,empty){return '<div class="card tablewrap"><table class="table"><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+(rows.length?rows.join(''):'<tr><td class="empty-state" colspan="'+headers.length+'"><div class="empty-icon">'+icon('file')+'</div><strong>'+empty+'</strong><br>No existen movimientos registrados.</td></tr>')+'</tbody></table></div>';}
function stat(label,value,sub,onClick){const key=/trabajador/i.test(label)?'users':/vacacion|asignaci|disfrutad/i.test(label)?'calendar':/incidencia|hora|semana/i.test(label)?'clock':/pag|bono|importe/i.test(label)?'coins':'file';return '<div class="card stat'+(onClick?' clickable':'')+'"'+(onClick?' role="button" tabindex="0" onclick="'+onClick+'" onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();'+onClick+'}"':'')+'><div class="stathead"><span>'+label+'</span><span class="staticon">'+icon(key)+'</span></div><div class="value">'+value+'</div><div class="foot">'+sub+'</div></div>';}
function header(section,title,desc,action){return '<div class="head"><div><div class="eyebrow">'+section+'</div><h1>'+title+'</h1><p>'+desc+'</p></div><div class="actions">'+(action||'')+'</div></div>';}
function actionDelete(table,id){return '<button class="btn" onclick="removeRecord(\''+table+'\',\''+id+'\')">Eliminar</button>';}
function sectionNav(group){const groups={personas:[['trabajadores','Trabajadores'],['vacaciones','Vacaciones'],['permisos','Permisos y ausencias'],['incidencias','Incidencias']],pagos:[['partners','Partners'],['horas','Horas extra'],['pagos','Pagos adicionales'],['pendientes','Pendientes'],['bonos','Bonos']]},tabs=groups[group]||[];return '<nav class="section-nav" aria-label="Secciones de '+(group==='personas'?'personas':'pagos')+'">'+tabs.map(([page,label])=>'<button class="section-tab '+(state.page===page?'active':'')+'" onclick="go(\''+page+'\')">'+label+'</button>').join('')+'</nav>';}
function renderWorkers(){return table(['Agente','Sociedad','Mail','Fecha alta','Fecha baja','Motivo','Acciones'],visibleWorkers().filter(w=>inRange(w.hire_date,'workers')).map(w=>'<tr><td>'+esc(w.agent)+'</td><td>'+esc(w.company)+'</td><td>'+esc(w.email||'-')+'</td><td>'+fmt(w.hire_date)+'</td><td>'+fmt(w.termination_date)+'</td><td>'+esc(w.termination_reason||'—')+'</td><td><button class="btn" onclick="showWorkerProfile(\''+w.id+'\')">Ver ficha</button></td></tr>'),'Todavía no hay trabajadores en esta vista.');}
function profileSection(title,items,empty){return '<section class="profile-block"><h3>'+title+'</h3>'+(items.length?items.slice(0,6).map(x=>'<div class="detailrow"><span>'+x+'</span></div>').join(''):'<small>'+empty+'</small>')+'</section>';}
function showWorkerProfile(id){const w=state.workers.find(x=>x.id===id);if(!w)return;const vacations=state.vacations.filter(x=>x.worker_id===id).sort((a,b)=>b.start_date.localeCompare(a.start_date)).map(x=>esc(fmt(x.start_date)+'–'+fmt(x.end_date)+' · '+x.days_count+' días')),leaves=state.leaves.filter(x=>x.worker_id===id).sort((a,b)=>b.start_date.localeCompare(a.start_date)).map(x=>esc(x.leave_type+' · '+fmt(x.start_date)+' · '+(x.days_count||0)+' días')),incidents=state.incidents.filter(x=>x.worker_id===id).sort((a,b)=>b.incident_date.localeCompare(a.incident_date)).map(x=>esc(x.incident_type+' · '+fmt(x.incident_date)+' · '+x.duration_minutes+' min')),payments=state.payments.filter(x=>x.worker_id===id).sort((a,b)=>b.payment_date.localeCompare(a.payment_date)).map(x=>esc(x.concept+' · '+money(x.amount)+' · '+fmt(x.payment_date))).concat(state.obligations.filter(x=>x.worker_id===id&&obligationStatus(x)!=='No corresponde').map(x=>esc((x.obligation_type==='Formación'?'Formación':'Incentivo Partner')+' · '+(x.amount===null?'Importe sin cuantía':money(x.amount))+' · '+fmt(x.payroll_month)))),hours=state.hours.filter(x=>x.worker_id===id).sort((a,b)=>b.work_date.localeCompare(a.work_date)).map(x=>esc(x.concept+' · '+x.hours+' h · '+money(x.amount)+' · '+fmt(x.work_date))),partners=state.partners.filter(x=>x.referred_worker_id===id).map(x=>esc('Referido por '+x.referrer_name+' · '+fmt(x.incorporation_date)+' · '+x.status));modal('Ficha de trabajador','<div class="profile-summary"><div><h3>'+esc(w.agent)+'</h3><p>'+esc(w.company)+' · '+esc(w.email||'Sin correo')+'</p><p>Alta: '+fmt(w.hire_date)+' · Baja: '+fmt(w.termination_date)+(w.termination_reason?' · '+esc(w.termination_reason):'')+'</p></div><button class="btn" onclick="editWorker(\''+id+'\')">Editar ficha</button></div><div class="profile-grid">'+profileSection('Vacaciones',vacations,'Sin periodos registrados')+profileSection('Permisos y ausencias',leaves,'Sin registros')+profileSection('Incidencias',incidents,'Sin incidencias')+profileSection('Pagos',payments,'Sin pagos ni previsiones')+profileSection('Horas extra',hours,'Sin horas registradas')+profileSection('Partners',partners,'Sin referencias asociadas')+'</div>');}
function editWorker(id){const w=state.workers.find(x=>x.id===id);if(!w)return;formWrap('Editar ficha de trabajador',field('Nombre y apellidos','agent','text',true,'value="'+esc(w.agent)+'"')+selectField('Sociedad','company',societyOptions(w.company))+field('Mail corporativo (opcional)','email','email',false,'value="'+esc(w.email==='-'?'':w.email||'')+'"')+field('Fecha de alta','hire_date','date',true,'value="'+esc(w.hire_date)+'"')+field('Fecha de baja','termination_date','date',false,'value="'+esc(w.termination_date||'')+'"')+textarea('Motivo de finalización','termination_reason'),'Guardar cambios','saveWorkerEdit');$('termination_reason').value=w.termination_reason||'';window.editingWorkerId=id;}
async function saveWorkerEdit(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus'),id=window.editingWorkerId;b.disabled=true;try{const hire=$('hire_date').value,term=$('termination_date').value||null,email=$('email').value.trim().toLowerCase()||'-';if(term&&term<hire)throw Error('La fecha de baja no puede ser anterior al alta.');if(email!=='-'&&state.workers.some(w=>w.id!==id&&String(w.email||'').toLowerCase()===email))throw Error('Ya existe otro trabajador con ese correo.');await update('workers',id,{agent:$('agent').value.trim(),company:$('company').value,email,hire_date:hire,termination_date:term,termination_reason:$('termination_reason').value.trim()||null});closeModal();await loadAll();toast('Ficha actualizada.');}catch(err){s.textContent=err.message;b.disabled=false;}}
function societyOptions(selected=''){return '<option value="">Seleccionar sociedad</option>'+state.societies.filter(x=>x.active||x.name===selected).map(x=>'<option '+(x.name===selected?'selected':'')+'>'+esc(x.name)+'</option>').join('');}
function showSocietyForm(name=''){const current=state.societies.find(x=>x.name===name);window.editingSocietyName=current?.name||null;formWrap(current?'Modificar sociedad':'Añadir sociedad',field('Nombre de la sociedad','society_name','text',true,'value="'+esc(current?.name||'')+'"')+'<div class="notice">El nombre se actualizará también en las fichas históricas que la utilizan.</div>',current?'Guardar cambios':'Añadir sociedad','saveSociety');}
async function saveSociety(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus'),old=window.editingSocietyName,name=$('society_name').value.trim();b.disabled=true;try{if(!name)throw Error('Indica el nombre de la sociedad.');if(state.societies.some(x=>norm(x.name)===norm(name)&&x.name!==old))throw Error('Ya existe una sociedad con ese nombre.');const db=client();const result=old?await db.from('societies').update({name,updated_at:new Date().toISOString()}).eq('name',old):await db.from('societies').insert({name});if(result.error)throw result.error;closeModal();await loadAll();toast(old?'Sociedad actualizada.':'Sociedad añadida.');}catch(err){s.textContent=err.message;b.disabled=false;}}
async function toggleSociety(name){const society=state.societies.find(x=>x.name===name);if(!society)return;const {error}=await client().from('societies').update({active:!society.active,updated_at:new Date().toISOString()}).eq('name',name);if(error){toast(error.message);return;}await loadAll();toast(society.active?'Sociedad desactivada.':'Sociedad activada.');}
function showNewWorker(){formWrap('Nuevo trabajador',field('Nombre y apellidos','agent')+selectField('Sociedad','company',societyOptions())+field('Mail corporativo (opcional)','email','email',false)+field('Fecha de alta','hire_date','date')+field('Fecha de baja','termination_date','date',false)+textarea('Motivo de finalización','termination_reason'),'Guardar trabajador','saveWorker');}
async function saveWorker(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus');b.disabled=true;try{const hire=$('hire_date').value,term=$('termination_date').value||null,email=$('email').value.trim().toLowerCase()||'-';if(term&&term<hire)throw Error('La fecha de baja no puede ser anterior al alta.');if(email!=='-'&&state.workers.some(w=>String(w.email||'').toLowerCase()===email))throw Error('Ya existe un trabajador con ese correo.');await insert('workers',{agent:$('agent').value.trim(),company:$('company').value,email,hire_date:hire,termination_date:term,termination_reason:$('termination_reason').value.trim()||null});closeModal();await loadAll();toast('Trabajador guardado.');}catch(err){s.textContent=err.message;b.disabled=false;}}
function downloadWorkersTemplate(){const rows=[['AGENTE','SOCIEDAD','MAIL','FECHA ALTA','FECHA DE BAJA','FINALIZACION CONTRATO'],['','','','','','']];const ws=XLSX.utils.aoa_to_sheet(rows),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Trabajadores');XLSX.writeFile(wb,'plantilla-trabajadores-acerca.xlsx');}
function showExcelImport(){modal('Importación masiva de trabajadores','<p>Sube el Excel de nóminas. Se buscará la hoja con encabezados compatibles aunque no sea la primera.</p><div class="notice">Se reconocen nombre, sociedad, correo, fecha de alta y baja, y motivo de finalización. Revisa las asignaciones de sociedad antes de importar.</div><div class="actions"><button class="btn" type="button" onclick="downloadWorkersTemplate()">'+icon('download')+' Descargar plantilla</button></div><div class="field"><label>Archivo Excel o CSV</label><input id="workersExcel" type="file" accept=".xlsx,.xls,.csv"></div><div id="workersImportStatus" class="notice">Selecciona el archivo para ver la vista previa.</div><div id="workersImportCompanies" class="import-company-list" style="display:none"></div><div id="workersImportPreview"></div><div class="actions" style="justify-content:flex-end"><button class="btn primary" id="confirmWorkersImport" type="button" disabled>Importar trabajadores</button></div>');window.pendingWorkersImport=null;$('workersExcel').addEventListener('change',previewExcel);$('confirmWorkersImport').addEventListener('click',saveWorkersExcel);}
function excelDate(v){if(v===null||v===undefined||v==='')return null;if(v instanceof Date&&!isNaN(v))return [v.getFullYear(),String(v.getMonth()+1).padStart(2,'0'),String(v.getDate()).padStart(2,'0')].join('-');if(typeof v==='number'&&window.XLSX){const d=XLSX.SSF.parse_date_code(v);if(d)return [d.y,String(d.m).padStart(2,'0'),String(d.d).padStart(2,'0')].join('-');}const s=String(v).trim();if(!s||s==='-')return null;let m=s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);if(m){let a=Number(m[1]),b=Number(m[2]),year=m[3],day,month;if(a>12&&b<=12){day=a;month=b;}else if(b>12&&a<=12){month=a;day=b;}else{day=a;month=b;}if(month<1||month>12||day<1||day>31)return 'INVALID';const parsed=new Date(Number(year),month-1,day);if(parsed.getFullYear()!==Number(year)||parsed.getMonth()!==month-1||parsed.getDate()!==day)return 'INVALID';return year+'-'+String(month).padStart(2,'0')+'-'+String(day).padStart(2,'0');}m=s.match(/^(\d{4})[\/.-](\d{1,2})[\/.-](\d{1,2})$/);if(m)return m[1]+'-'+m[2].padStart(2,'0')+'-'+m[3].padStart(2,'0');const d=new Date(s);return isNaN(d)?'INVALID':[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function findHeader(headers,aliases){const normalized=headers.map(norm);for(const alias of aliases){const exact=normalized.indexOf(norm(alias));if(exact>=0)return exact;}return -1;}
function importSheetRows(wb){const aliases={agent:['AGENTE','NOMBRE','NOMBRE Y APELLIDOS','APELLIDOS Y NOMBRE','TRABAJADOR','EMPLEADO','AGENT','NOMBRE COMPLETO','COLABORADOR'],company:['SOCIEDAD','EMPRESA','COMPANY','RAZON SOCIAL','ENTIDAD'],email:['MAIL','EMAIL','CORREO','CORREO ELECTRONICO','CORREO CORPORATIVO','MAIL CORPORATIVO','E MAIL'],hire_date:['FECHA ALTA','FECHA DE ALTA','FECHA INCORPORACION','FECHA DE INCORPORACION','FECHA INGRESO','FECHA DE INGRESO','ALTA','FECHA INICIO'],termination_date:['FECHA DE BAJA','FECHA BAJA','FECHA FINALIZACION','FECHA DE FINALIZACION','FECHA FIN','BAJA'],termination_reason:['MOTIVO','MOTIVO BAJA','MOTIVO DE BAJA','CAUSA BAJA','FINALIZACION CONTRATO','FINALIZACION DE CONTRATO','FIN DE CONTRATO']};let best=null;for(const name of wb.SheetNames){const rows=XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:'',raw:true});for(let i=0;i<Math.min(rows.length,30);i++){const map={};Object.keys(aliases).forEach(k=>map[k]=findHeader((rows[i]||[]).map(String),aliases[k]));const score=['agent','company','hire_date'].filter(k=>map[k]>=0).length+['email','termination_date','termination_reason'].filter(k=>map[k]>=0).length*.1;if(score>=3&&(!best||score>best.score))best={name,rows,headerAt:i,map,score};}}return best;}
function suggestedSociety(value){const key=norm(value);if(!key)return '';const tokens=key.match(/[a-z0-9]+/g)||[];let best='',bestScore=0;for(const society of state.societies){const candidate=norm(society.name),parts=candidate.match(/[a-z0-9]+/g)||[];let score=candidate===key?1:0;for(const token of tokens){if(token.length>=5&&parts.some(part=>part===token||part.startsWith(token)||token.startsWith(part)))score+=.45;}if(score>bestScore){bestScore=score;best=society.name;}}return bestScore>=.45?best:'';}
function renderImportSocietyChoices(){const box=$('workersImportCompanies');if(!box)return;const rows=window.pendingWorkersImport||[],missing=[...new Set(rows.map(x=>x.raw_company).filter(x=>x&&!normalizeCompany(x)))];window.importSocietyMap=window.importSocietyMap||{};box.innerHTML=missing.length?'<p><b>Revisa las sociedades del archivo</b></p><p>Confirma el destino de cada nombre distinto antes de importar. Puedes elegir una sociedad existente o crear una nueva.</p>'+missing.map(raw=>{const suggestion=suggestedSociety(raw),value=window.importSocietyMap[raw]||'';return '<div class="import-company"><label>'+esc(raw)+(suggestion?'<small>Posible coincidencia: '+esc(suggestion)+'</small>':'')+'</label><select data-import-company="'+esc(raw)+'"><option value="">Seleccionar destino…</option>'+state.societies.map(s=>'<option value="'+esc(s.name)+'" '+(value===s.name?'selected':'')+'>'+esc(s.name)+'</option>').join('')+'<option value="__create__" '+(value==='__create__'?'selected':'')+'>Crear sociedad nueva con este nombre</option></select></div>';}).join(''):'<p>Todas las sociedades del archivo coinciden con el catálogo.</p>';box.style.display=missing.length?'block':'none';box.querySelectorAll('[data-import-company]').forEach(select=>select.addEventListener('change',()=>{window.importSocietyMap[select.dataset.importCompany]=select.value;validateImportReady();}));}
function validateImportReady(){const rows=window.pendingWorkersImport||[],ready=rows.length>0&&[...new Set(rows.map(x=>x.raw_company).filter(x=>x&&!normalizeCompany(x)))].every(x=>window.importSocietyMap?.[x]);const btn=$('confirmWorkersImport');if(btn)btn.disabled=!ready;return ready;}
async function previewExcelRaw(e){const f=e.target.files?.[0],status=$('workersImportStatus'),preview=$('workersImportPreview'),btn=$('confirmWorkersImport');btn.disabled=true;preview.innerHTML='';$('workersImportCompanies').innerHTML='';window.pendingWorkersImport=null;window.importSocietyMap={};if(!f)return;try{if(!window.XLSX)throw Error('No se ha cargado el lector Excel. Recarga la página con Ctrl+F5.');const wb=XLSX.read(await f.arrayBuffer(),{type:'array',cellDates:true,raw:true}),found=importSheetRows(wb);if(!found)throw Error('No encuentro una hoja con las columnas obligatorias Nombre/Agente, Sociedad y Fecha de alta. He revisado las primeras 30 filas de todas las hojas.');const {rows,headerAt,map}=found,parsed=rows.slice(headerAt+1).filter(r=>r.some(v=>String(v??'').trim())).map((r,i)=>{const agent=String(r[map.agent]??'').trim(),raw=String(r[map.company]??'').trim(),company=normalizeCompany(raw),email=map.email>=0?(String(r[map.email]??'').trim().toLowerCase()||'-'):'-',hire=excelDate(r[map.hire_date]),term=map.termination_date>=0?excelDate(r[map.termination_date]):null,reason=map.termination_reason>=0?String(r[map.termination_reason]??'').trim():'',errors=[];if(!agent)errors.push('Falta nombre');if(!raw)errors.push('Falta sociedad');if(!hire||hire==='INVALID')errors.push('Fecha de alta no válida');if(term==='INVALID')errors.push('Fecha de baja no válida');if(term&&hire&&term<hire)errors.push('Baja anterior al alta');if(email!=='-'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))errors.push('Mail no válido');return {agent,company:company||raw,raw_company:raw,email,hire_date:hire,termination_date:term==='INVALID'?null:term,termination_reason:reason||null,errors,row:headerAt+i+2};});if(!parsed.length)throw Error('El Excel no contiene filas de trabajadores.');const invalid=parsed.filter(x=>x.errors.length);window.pendingWorkersImport=parsed.filter(x=>x.errors.length===0);status.textContent=parsed.length+' filas leídas en «'+found.name+'» · '+invalid.length+' con errores · '+window.pendingWorkersImport.length+' listas para importar.';renderImportSocietyChoices();preview.innerHTML='<div class="card tablewrap" style="max-height:260px;overflow:auto"><table class="table"><thead><tr><th>Nombre</th><th>Sociedad</th><th>Mail</th><th>Alta</th><th>Baja</th><th>Motivo</th><th>Validación</th></tr></thead><tbody>'+parsed.slice(0,150).map(x=>'<tr><td>'+esc(x.agent||'-')+'</td><td>'+esc(x.company||'-')+'</td><td>'+esc(x.email)+'</td><td>'+esc(x.hire_date||'-')+'</td><td>'+esc(x.termination_date||'-')+'</td><td>'+esc(x.termination_reason||'-')+'</td><td><span class="pill '+(x.errors.length?'red':'green')+'">'+esc(x.errors.join(', ')||(!normalizeCompany(x.raw_company)?'Revisar sociedad':'Correcto'))+'</span></td></tr>').join('')+'</tbody></table></div><small>Hoja: '+esc(found.name)+' · Vista previa de '+Math.min(parsed.length,150)+' de '+parsed.length+' filas.</small>';if(invalid.length)status.textContent+=' Corrige las filas con errores en el Excel y vuelve a seleccionarlo.';else status.textContent+=' Revisa las sociedades y continúa.';validateImportReady();}catch(err){status.textContent='No se ha podido leer el Excel: '+err.message;btn.disabled=true;}}
async function previewExcel(e){await previewExcelRaw(e);const status=$('workersImportStatus'),btn=$('confirmWorkersImport'),rows=window.pendingWorkersImport||[];if(!rows.length||!client())return;try{const {data,error}=await client().from('workers').select('agent,company,email,hire_date');if(error)throw error;const keyOf=x=>x.email&&x.email!=='-'?'mail:'+String(x.email).trim().toLowerCase():'row:'+norm(x.agent)+'|'+norm(x.company)+'|'+x.hire_date,existing=new Set((data||[]).map(keyOf)),seen=new Set(),dupes=new Set();rows.forEach(x=>{const key=keyOf(x);if(existing.has(key)||seen.has(key))dupes.add(key);seen.add(key);});if(!dupes.size)return;window.pendingWorkersImport=rows.filter(x=>!dupes.has(keyOf(x)));const tr=[...$('workersImportPreview').querySelectorAll('tbody tr')];tr.forEach(row=>{const cells=row.cells,item=rows.find(x=>x.agent===cells[0]?.textContent&&x.company===cells[1]?.textContent&&x.email===cells[2]?.textContent);if(item&&dupes.has(keyOf(item))){const badge=cells[6]?.querySelector('.pill');if(badge){badge.className='pill amber';badge.textContent='Duplicado; se omitirá';}}});status.textContent+=' '+dupes.size+' registro(s) duplicado(s) detectados; se omitirán. '+window.pendingWorkersImport.length+' listos para importar.';renderImportSocietyChoices();validateImportReady();}catch(err){window.pendingWorkersImport=[];btn.disabled=true;status.textContent='No se pudieron comprobar duplicados en Supabase: '+err.message;}}
async function saveWorkersExcel(){const btn=$('confirmWorkersImport'),status=$('workersImportStatus'),rows=window.pendingWorkersImport||[];if(!rows.length){status.textContent='No hay filas válidas para importar.';return;}if(!validateImportReady()){status.textContent='Elige un destino para cada sociedad señalada.';return;}if(!client()){status.textContent='No hay conexión con Supabase. Cierra sesión y vuelve a entrar.';return;}btn.disabled=true;btn.textContent='Importando…';status.textContent='Preparando sociedades…';try{const newNames=[...new Set(rows.map(x=>x.raw_company).filter(raw=>!normalizeCompany(raw)&&window.importSocietyMap[raw]==='__create__'))];if(newNames.length){const {error:societyError}=await client().from('societies').upsert(newNames.map(name=>({name})),{onConflict:'name',ignoreDuplicates:true});if(societyError)throw Error('No se pudieron crear las sociedades nuevas: '+societyError.message);await loadAll();}const mapped=rows.map(row=>({...row,company:normalizeCompany(row.raw_company)||window.importSocietyMap[row.raw_company]}));if(mapped.some(row=>!row.company||row.company==='__create__'))throw Error('No se pudo asignar el nombre de una sociedad.');status.textContent='Comprobando duplicados…';const {data:existing,error}=await client().from('workers').select('agent,company,email,hire_date');if(error)throw error;const keys=new Set((existing||[]).map(x=>x.email&&x.email!=='-'?'mail:'+x.email.toLowerCase():'row:'+norm(x.agent)+'|'+norm(x.company)+'|'+x.hire_date));const unique=[];let skipped=0;for(const row of mapped){const key=row.email&&row.email!=='-'?'mail:'+row.email.toLowerCase():'row:'+norm(row.agent)+'|'+norm(row.company)+'|'+row.hire_date;if(keys.has(key)){skipped++;continue;}keys.add(key);unique.push({agent:row.agent,company:row.company,email:row.email||'-',hire_date:row.hire_date,termination_date:row.termination_date||null,termination_reason:row.termination_reason||null});}if(!unique.length)throw Error('Todos los registros del Excel ya existen en la plantilla. No se ha añadido ninguno.');let added=0,failures=[];for(let i=0;i<unique.length;i+=25){const batch=unique.slice(i,i+25);status.textContent='Importando '+Math.min(i+batch.length,unique.length)+' de '+unique.length+' trabajadores…';const {error:batchError}=await client().from('workers').insert(batch);if(!batchError){added+=batch.length;continue;}for(let j=0;j<batch.length;j++){const {error:rowError}=await client().from('workers').insert(batch[j]);if(rowError)failures.push(batch[j].agent+': '+rowError.message);else added++;}}await loadAll();if(failures.length){status.textContent='Importación parcial: '+added+' añadidos, '+skipped+' duplicados omitidos y '+failures.length+' con error. Primer error: '+failures[0];btn.disabled=false;btn.textContent='Reintentar filas con error';window.pendingWorkersImport=unique.filter(x=>failures.some(f=>f.startsWith(x.agent+':')));}else{status.textContent='Importación completada: '+added+' trabajadores añadidos; '+skipped+' duplicados omitidos.';btn.textContent='Importación completada';window.pendingWorkersImport=[];setTimeout(closeModal,1400);}}catch(err){status.textContent='No se ha podido importar: '+(err.message||String(err))+' Si aparece un error de permisos o tabla inexistente, hay que revisar la configuración de Supabase.';btn.disabled=false;btn.textContent='Reintentar importación';}}
function vacationEntitlement(w,year){const start=new Date(year,0,1),end=new Date(year,11,31),hire=w.hire_date?new Date(w.hire_date+'T12:00:00'):start,effective=hire>start?hire:start;if(effective>end)return {total:0,weeks:0,singles:0};const daysInYear=Math.round((end-start)/86400000)+1,eligibleDays=Math.round((end-effective)/86400000)+1,total=Math.round(32*eligibleDays/daysInYear),weeks=Math.min(28,Math.floor(total/7)*7);return {total,weeks,singles:total-weeks};}
function vacationQuota(w,year,kind){const q=vacationEntitlement(w,year);return kind==='week'?q.weeks:q.singles;}
function daysInVacationYear(v,year){const start=v.start_date>year+'-01-01'?v.start_date:year+'-01-01',end=v.end_date<year+'-12-31'?v.end_date:year+'-12-31';if(start>end)return 0;return calendarDaysBetween(start,end);}
function vacationUsed(workerId,year,kind){return state.vacations.filter(v=>v.worker_id===workerId&&v.kind===kind).reduce((sum,v)=>sum+daysInVacationYear(v,year),0);}
function vacationHistoryForWorker(id){const rows=state.vacations.filter(v=>v.worker_id===id).sort((a,b)=>b.start_date.localeCompare(a.start_date));return '<div class="card panel"><h3>Periodos registrados · '+esc(workerName(id))+'</h3>'+table(['Desde','Hasta','Tipo','Días','Acciones'],rows.map(v=>'<tr><td>'+fmt(v.start_date)+'</td><td>'+fmt(v.end_date)+'</td><td>'+esc(v.kind==='week'?'Semana':'Días sueltos')+'</td><td>'+esc(v.days_count)+'</td><td><button class="btn danger" onclick="deleteVacationRecord(\''+esc(v.id)+'\',\'history\',\''+esc(id)+'\')">Eliminar</button></td></tr>'),'No hay vacaciones registradas para esta persona.')+'</div>';}
function vacationOverview(){const year=state.calendarYear,rows=visibleWorkers().slice().sort((a,b)=>a.agent.localeCompare(b.agent,'es')).map(w=>{const weekQuota=vacationQuota(w,year,'week'),singleQuota=vacationQuota(w,year,'single'),weekUsed=vacationUsed(w.id,year,'week'),singleUsed=vacationUsed(w.id,year,'single'),available=weekQuota-weekUsed+singleQuota-singleUsed;return '<tr><td><b>'+esc(w.agent)+'</b></td><td>'+esc(w.company||'—')+'</td><td>'+number(weekQuota/7)+' sem. <small>('+number(weekQuota)+' días)</small></td><td>'+number(weekUsed/7)+' sem. <small>('+number(weekUsed)+' días)</small></td><td>'+number(singleQuota)+' días</td><td>'+number(singleUsed)+' días</td><td><b>'+number(available)+' días</b></td></tr>';});return '<div class="card panel vacation-overview"><div class="overview-heading"><div><h3>Resumen de vacaciones · '+year+'</h3><p>Saldos de toda la plantilla visible, según el filtro Plantilla.</p></div></div>'+table(['Trabajador','Sociedad','Semanas asignadas','Semanas disfrutadas','Días sueltos asignados','Días sueltos disfrutados','Saldo disponible'],rows,'No hay trabajadores en la plantilla visible.')+'</div>';}
function toggleVacationOverview(){state.vacationShowAll=!state.vacationShowAll;state.vacationWorkerId='';render();}
function number(value){return Number(value||0).toLocaleString('es-ES',{maximumFractionDigits:2});}
function renderVacations(){const year=state.calendarYear,selected=state.workers.find(w=>w.id===state.vacationWorkerId&&workerVisible(w.id));if(state.vacationWorkerId&&!selected)state.vacationWorkerId='';const weekQuota=selected?vacationQuota(selected,year,'week'):0,singleQuota=selected?vacationQuota(selected,year,'single'):0,weekUsed=selected?vacationUsed(selected.id,year,'week'):0,singleUsed=selected?vacationUsed(selected.id,year,'single'):0,yearStart=year+'-01-01',yearEnd=year+'-12-31',yearRecords=state.vacations.filter(v=>workerVisible(v.worker_id)&&v.start_date<=yearEnd&&v.end_date>=yearStart),used=yearRecords.reduce((sum,v)=>sum+daysInVacationYear(v,year),0),summary=selected?'<div class="card panel vacation-summary"><div><div class="eyebrow">FICHA DE VACACIONES</div><h2>'+esc(selected.agent)+'</h2><p>'+esc(selected.company)+'</p></div><div class="grid stats">'+stat('Semanas asignadas',weekQuota/7,'equivalente a '+weekQuota+' días')+stat('Días sueltos asignados',singleQuota,'Bolsa anual')+stat('Semanas utilizadas',(weekUsed/7).toLocaleString('es-ES',{maximumFractionDigits:2}),weekUsed+' días consumidos')+stat('Días sueltos utilizados',singleUsed,'de '+singleQuota+' disponibles')+stat('Saldo disponible',(weekQuota-weekUsed)+(singleQuota-singleUsed),'Días restantes')+'</div></div>':'<div class="card panel"><p>'+(state.vacationShowAll?'Resumen de saldos de la plantilla visible. Puedes buscar una persona para consultar su ficha.':'Busca una persona para consultar su saldo. El calendario general siempre muestra las vacaciones de toda la plantilla.')+'</p></div>';return '<div class="vacation-search-row"><div class="vacation-search">'+workerSearchField('Buscar trabajador','vacation_worker',state.vacationWorkerId)+'</div><button class="btn" type="button" onclick="toggleVacationOverview()">'+(state.vacationShowAll?'Ocultar todo':'Mostrar todo')+'</button></div>'+(state.vacationShowAll?vacationOverview():'')+summary+(selected?vacationHistoryForWorker(selected.id):'')+'<div class="grid stats">'+stat('Días disfrutados',used,'En '+year)+stat('Periodos del año',yearRecords.length,'Vacaciones registradas')+stat('Plantilla visible',visibleWorkers().length,'Según el filtro general')+'</div>'+calendar()+'<div class="notice">El saldo se calcula por año natural. Los periodos que cruzan años descuentan en cada año solo los días de sus fechas correspondientes. La asignación anual conserva 28 días en semanas y 4 días sueltos, con prorrateo por fecha de alta.</div>';}
function showVacationHistory(id){const rows=state.vacations.filter(v=>v.worker_id===id);modal('Vacaciones · '+workerName(id),rows.length?rows.map(v=>'<div class="detailrow"><span>'+fmt(v.start_date)+' al '+fmt(v.end_date)+' · '+(v.kind==='week'?'Semana':'Días sueltos')+'</span><b>'+v.days_count+' días</b><span class="actions">'+actionDelete('vacation_records',v.id)+'</span></div>').join(''):'<p>No hay vacaciones registradas.</p>');}
function calendar(){const first=new Date(state.calendarYear,state.calendarMonth,1),last=new Date(state.calendarYear,state.calendarMonth+1,0),offset=(first.getDay()+6)%7;let cells='';for(let i=0;i<offset;i++)cells+='<span></span>';for(let d=1;d<=last.getDate();d++){const date=isoDate(new Date(state.calendarYear,state.calendarMonth,d)),rows=state.vacations.filter(v=>workerVisible(v.worker_id)&&v.start_date<=date&&v.end_date>=date),names=rows.map(v=>workerName(v.worker_id)),types=new Set(rows.map(v=>v.kind||'week')),has=rows.length>0,typeClass=types.size>1?'hasvac-mixed':types.has('single')?'hasvac-single':'hasvac-week';cells+='<button title="'+esc(names.join(', '))+'" aria-label="'+d+(has?': '+esc(names.join(', ')):'')+'" class="'+(has?'hasvac '+typeClass:'')+'" onclick="calendarDay('+d+')">'+d+(has?'<small>'+rows.length+'</small>':'')+'</button>';}return '<div class="card panel" style="margin-top:15px"><div style="display:flex;justify-content:space-between;align-items:center"><h3>'+first.toLocaleDateString('es-ES',{month:'long',year:'numeric'})+'</h3><div><button class="btn" aria-label="Mes anterior" onclick="changeMonth(-1)">‹</button> <button class="btn" aria-label="Mes siguiente" onclick="changeMonth(1)">›</button></div></div><div class="calendar">'+['L','M','X','J','V','S','D'].map(x=>'<span>'+x+'</span>').join('')+cells+'</div><div class="calendar-legend"><span><i class="week"></i> Semana</span><span><i class="single"></i> Días sueltos</span><span><i class="mixed"></i> Coinciden</span></div></div>';}
function changeMonth(n){state.calendarMonth+=n;if(state.calendarMonth<0){state.calendarMonth=11;state.calendarYear--;}if(state.calendarMonth>11){state.calendarMonth=0;state.calendarYear++;}render();}
function calendarDay(day){const d=isoDate(new Date(state.calendarYear,state.calendarMonth,day));const rows=state.vacations.filter(v=>workerVisible(v.worker_id)&&v.start_date<=d&&v.end_date>=d);modal('Vacaciones · '+fmt(d),rows.length?rows.map(v=>'<div class="detailrow"><span>'+esc(workerName(v.worker_id))+' · '+esc(state.workers.find(w=>w.id===v.worker_id)?.company||'')+' · '+esc(v.kind==='week'?'Semana':'Días sueltos')+'</span><button class="btn danger" onclick="deleteVacationRecord(\''+esc(v.id)+'\',\'calendar\',\''+day+'\')">Eliminar periodo</button></div>').join(''):'<p>No hay vacaciones registradas este día.</p>');}
function showVacationForm(){formWrap('Registrar vacaciones',workerSearchField('Trabajador','worker_id')+selectField('Tipo','kind','<option value="week">Semana completa</option><option value="single">Días sueltos</option>')+field('Fecha de inicio','start_date','date')+field('Fecha de fin','end_date','date')+textarea('Observaciones','notes'),'Guardar vacaciones','saveVacation');}
function vacationSheet(wb){const aliases={name:['NOMBRE','TRABAJADOR','EMPLEADO','AGENTE','NOMBRE Y APELLIDOS'],start:['FECHA INICIO','FECHA DE INICIO','INICIO','DESDE'],end:['FECHA FIN','FECHA DE FIN','FIN','HASTA'],days:['DIAS NATURALES','DIAS','DURACION','DURACION DIAS']};let best=null;for(const name of wb.SheetNames){const rows=XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:'',raw:true});for(let i=0;i<Math.min(rows.length,40);i++){const map={};for(const key of Object.keys(aliases))map[key]=findHeader((rows[i]||[]).map(String),aliases[key]);if(Object.values(map).every(index=>index>=0)){best={name,rows,headerAt:i,map};break;}}if(best)break;}return best;}
function excelDateUS(value){if(value instanceof Date||typeof value==='number')return excelDate(value);const text=String(value??'').trim(),iso=text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);if(iso){const year=Number(iso[1]),month=Number(iso[2]),day=Number(iso[3]),date=new Date(year,month-1,day);return month>=1&&month<=12&&date.getFullYear()===year&&date.getMonth()===month-1&&date.getDate()===day?isoDate(date):'INVALID';}const match=text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(!match)return 'INVALID';const month=Number(match[1]),day=Number(match[2]),year=Number(match[3]);if(month<1||month>12||day<1||day>31)return 'INVALID';const date=new Date(year,month-1,day);return date.getFullYear()===year&&date.getMonth()===month-1&&date.getDate()===day?isoDate(date):'INVALID';}
function vacationImportKey(record){return [record.worker_id,record.start_date,record.end_date,record.kind].join('|');}
function vacationImportPreview(){const rows=state.vacationImportRows,host=$('vacationImportPreview'),status=$('vacationImportStatus');if(!host||!status)return;const workers=new Set(rows.filter(x=>x.worker_id).map(x=>x.worker_id)).size,correct=rows.filter(x=>x.worker_id&&!x.duplicate&&!x.errors.length).length,weeks=rows.filter(x=>x.worker_id&&x.record?.kind==='week'&&!x.errors.length&&!x.duplicate).length,singles=rows.filter(x=>x.worker_id&&x.record?.kind==='single'&&!x.errors.length&&!x.duplicate).length,duplicates=rows.filter(x=>x.duplicate).length,badDates=rows.filter(x=>x.errors.some(e=>e==='Fecha no válida'||e==='Días naturales no válidos')).length,mismatches=rows.filter(x=>x.errors.some(e=>e.startsWith('Las fechas'))).length,unresolved=rows.filter(x=>!x.worker_id).length,overlaps=rows.filter(x=>x.errors.some(e=>e.startsWith('Se solapa'))).length;status.innerHTML='<b>'+rows.length+'</b> periodos · '+workers+' trabajadores identificados · '+weeks+' semanas · '+singles+' días sueltos · '+correct+' correctos · '+unresolved+' por asignar · '+badDates+' fechas/duración errónea · '+mismatches+' discrepancias · '+overlaps+' solapamientos · '+duplicates+' duplicados';host.innerHTML='<div class="card tablewrap" style="max-height:360px;overflow:auto"><table class="table"><thead><tr><th>Nombre del Excel</th><th>Inicio</th><th>Fin</th><th>Días</th><th>Tipo</th><th>Asignación / resultado</th></tr></thead><tbody>'+rows.map((x,i)=>'<tr><td>'+esc(x.name||'—')+'</td><td>'+fmt(x.start)+'</td><td>'+fmt(x.end)+'</td><td>'+esc(x.days??'—')+'</td><td>'+esc(x.kind==='week'?'Semana':'Días sueltos')+'</td><td>'+(x.worker_id?'<b>'+esc(workerName(x.worker_id))+'</b> · '+esc(state.workers.find(w=>w.id===x.worker_id)?.company||''):'<div class="field"><label>Revisar asignación de trabajador</label>'+workerSearchField('Trabajador existente','vac_import_'+i)+'</div>')+(x.duplicate?'<span class="pill amber">Duplicado; se omitirá</span>':x.errors.length?'<span class="pill red">'+esc(x.errors.join('; '))+'</span>':'<span class="pill green">Correcto</span>')+'</td></tr>').join('')+'</tbody></table></div><small>Hoja: '+esc(window.vacationImportSheet||'')+' · Se han revisado todos los encabezados, incluidas las columnas posteriores a la I.</small>';}
function showVacationImport(){state.vacationImportRows=[];modal('Importar vacaciones desde Excel','<p>Selecciona el Excel. Se detectan las columnas necesarias por su encabezado; las demás se ignoran.</p><div class="notice">Formato de fechas de texto: MM/DD/YYYY. Se comprobará que los días naturales coincidan con el intervalo. Los duplicados y las filas con errores no se importan.</div><div class="field"><label>Archivo Excel o CSV</label><input id="vacationExcel" type="file" accept=".xlsx,.xls,.csv"></div><div id="vacationImportStatus" class="notice">Elige un archivo para analizarlo.</div><div id="vacationImportPreview"></div><div class="actions" style="justify-content:flex-end"><button class="btn primary" id="confirmVacationImport" type="button" disabled onclick="saveVacationImport()">Importar filas correctas</button></div>');$('vacationExcel').addEventListener('change',previewVacationImport);}
async function previewVacationImport(event){const file=event.target.files?.[0],status=$('vacationImportStatus'),button=$('confirmVacationImport');if(!file)return;status.textContent='Analizando archivo y comprobando trabajadores y duplicados…';button.disabled=true;try{if(!window.XLSX)throw Error('No está disponible el lector Excel. Recarga con Ctrl+F5.');const workbook=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true,raw:true}),sheet=vacationSheet(workbook);if(!sheet)throw Error('No se encuentran las columnas Nombre, Fecha inicio, Fecha fin y Días naturales.');window.vacationImportSheet=sheet.name;const visible=visibleWorkers(),{rows,map,headerAt}=sheet,parsed=rows.slice(headerAt+1).filter(row=>row.some(value=>String(value??'').trim())).map((row,index)=>{const name=String(row[map.name]??'').trim(),start=excelDateUS(row[map.start]),end=excelDateUS(row[map.end]),rawDays=String(row[map.days]??'').trim().replace(',','.'),days=Number(rawDays),errors=[];if(!start||start==='INVALID'||!end||end==='INVALID'||end<start)errors.push('Fecha no válida');if(!Number.isInteger(days)||days<1)errors.push('Días naturales no válidos');const actual=errors.includes('Fecha no válida')?null:calendarDaysBetween(start,end);if(actual!==null&&Number.isInteger(days)&&days!==actual)errors.push('Las fechas no coinciden con los días naturales (intervalo: '+actual+')');const kind=Number.isInteger(days)&&days>0&&days%7===0?'week':'single',matches=visible.filter(w=>norm(w.agent)===norm(name)),worker=matches.length===1?matches[0]:null;if(matches.length===0)errors.push('Trabajador no encontrado; asignación manual requerida');if(matches.length>1)errors.push('Nombre coincidente en varias fichas; selección manual requerida');return {name,start,end,days,kind,worker_id:worker?.id||null,matches:matches.map(w=>w.id),errors,rowNumber:headerAt+index+2,duplicate:false,record:!errors.some(error=>error.startsWith('Fecha no válida')||error.startsWith('Días naturales no válidos')||error.startsWith('Las fechas'))?{worker_id:worker?.id||null,start_date:start,end_date:end,kind,days_count:days,notes:'Importado desde '+file.name}:null};});const keys=new Set(state.vacations.map(v=>vacationImportKey(v))),seen=new Set();for(const item of parsed){if(!item.record||item.errors.some(error=>error.startsWith('Fecha no válida')||error.startsWith('Días naturales')||error.startsWith('Las fechas')))continue;const id=item.worker_id;if(!id)continue;const key=vacationImportKey({...item.record,worker_id:id});if(keys.has(key)||seen.has(key)){item.duplicate=true;item.errors.push('Duplicado');}seen.add(key);if(!item.duplicate&&state.vacations.some(v=>v.worker_id===id&&v.start_date<=item.end&&v.end_date>=item.start))item.errors.push('Se solapa con otro periodo existente');}state.vacationImportRows=parsed;vacationImportPreview();button.disabled=!parsed.length;}catch(error){status.textContent='No se pudo analizar el Excel: '+error.message;}}
async function saveVacationImport(){const rows=state.vacationImportRows,button=$('confirmVacationImport'),status=$('vacationImportStatus');if(!rows.length)return;button.disabled=true;const records=[],usedByYear=new Map(),seen=new Set();for(let i=0;i<rows.length;i++){const item=rows[i];if(item.duplicate||item.errors.some(error=>error.startsWith('Fecha no válida')||error.startsWith('Días naturales')||error.startsWith('Las fechas')||error.startsWith('Se solapa')))continue;const workerId=item.worker_id||$('vac_import_'+i)?.value,worker=state.workers.find(w=>w.id===workerId);if(!worker||!workerVisible(workerId)){item.errors.push('Asigna una ficha visible de trabajador antes de importar');continue;}item.worker_id=workerId;item.record={worker_id:workerId,start_date:item.start,end_date:item.end,kind:item.kind,days_count:item.days,notes:'Importado desde Excel'};const key=vacationImportKey(item.record);if(seen.has(key)||state.vacations.some(v=>vacationImportKey(v)===key)){item.duplicate=true;item.errors.push('Duplicado');continue;}if(state.vacations.some(v=>v.worker_id===workerId&&v.start_date<=item.end&&v.end_date>=item.start)||records.some(v=>v.worker_id===workerId&&v.start_date<=item.end&&v.end_date>=item.start)){item.errors.push('Se solapa con otro periodo');continue;}let valid=true;for(let year=Number(item.start.slice(0,4));year<=Number(item.end.slice(0,4));year++){const part=daysInVacationYear(item.record,year),bucket=workerId+'|'+year+'|'+item.kind,used=usedByYear.get(bucket)??vacationUsed(workerId,year,item.kind);if(used+part>vacationQuota(worker,year,item.kind)){item.errors.push('Supera saldo de '+year);valid=false;break;}usedByYear.set(bucket,used+part);}if(valid){records.push(item.record);seen.add(key);}}vacationImportPreview();if(!records.length){button.disabled=false;toast('No hay filas correctas para importar. Revisa las asignaciones y errores.');return;}status.textContent='Importando '+records.length+' periodos correctos…';try{const {error}=await client().from('vacation_records').insert(records);if(error)throw error;await loadAll();toast(records.length+' periodos de vacaciones importados.');closeModal();}catch(error){button.disabled=false;status.textContent='No se pudieron guardar los periodos: '+error.message;}}
async function saveVacation(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus');b.disabled=true;try{const start=$('start_date').value,end=$('end_date').value;if(!start||!end||end<start)throw Error('Indica un intervalo de fechas válido.');const days=calendarDaysBetween(start,end),w=state.workers.find(x=>x.id===$('worker_id').value);if(!w||!workerVisible(w.id))throw Error('Busca y selecciona un trabajador visible en el filtro general.');const kind=$('kind').value;if(state.vacations.some(v=>v.worker_id===w.id&&v.start_date<=end&&v.end_date>=start))throw Error('Este periodo se solapa con otras vacaciones del trabajador.');if(kind==='week'&&(days%7!==0||days<7))throw Error('Las semanas deben registrarse en bloques completos de 7 días naturales.');let cursor=new Date(start+'T12:00:00');while(isoDate(cursor)<=end){const year=cursor.getFullYear(),partEnd=isoDate(new Date(year,11,31))<end?isoDate(new Date(year,11,31)):end,partDays=daysInVacationYear({start_date:isoDate(cursor),end_date:partEnd},year),quota=vacationQuota(w,year,kind),used=vacationUsed(w.id,year,kind);if(used+partDays>quota)throw Error('El periodo supera el saldo de '+(kind==='week'?'semanas':'días sueltos')+' de '+year+'. Disponible: '+Math.max(0,quota-used)+' días; este tramo consume '+partDays+'.');cursor=new Date(year+1,0,1,12);}await insert('vacation_records',{worker_id:w.id,start_date:start,end_date:end,kind,days_count:days,notes:$('notes').value||null});closeModal();await loadAll();toast(days+' días de vacaciones registrados.');}catch(err){s.textContent=err.message;b.disabled=false;}}
