function incidentTimingFields(type){return type==='Impuntualidad'?field('Hora prevista de entrada','planned_time','time')+field('Hora real de entrada','incident_time','time'):'<div class="field"><label for="incident_time">Hora de inicio del abandono</label><input id="incident_time" type="time" required></div>'+field('Hora de reincorporación','end_time','time')+'<small>Si la reincorporación es al día siguiente, se calculará correctamente.</small>';}
function updateIncidentFields(){const type=$('incident_type')?.value,box=$('incidentTiming');if(!box)return;box.innerHTML=incidentTimingFields(type)+'<div class="notice" id="incidentDurationPreview">Indica las horas para calcular automáticamente la duración.</div>';['planned_time','incident_time','end_time'].forEach(id=>$(id)?.addEventListener('change',updateIncidentDuration));}
function updateIncidentDuration(){const type=$('incident_type')?.value,planned=$('planned_time')?.value,start=$('incident_time')?.value,end=$('end_time')?.value,preview=$('incidentDurationPreview');if(!preview)return;let mins=null;if(type==='Impuntualidad'&&planned&&start){mins=timeToMinutes(start)-timeToMinutes(planned);if(mins<0){preview.textContent='La hora real es anterior a la hora prevista: se registrarán 0 minutos.';return;} }else if(type==='Abandono de puesto'&&start&&end){mins=timeToMinutes(end)-timeToMinutes(start);if(mins<0)mins+=1440;}if(mins===null){preview.textContent='Indica las horas para calcular automáticamente la duración.';return;}preview.textContent='Duración calculada automáticamente: '+mins+' minutos ('+Math.floor(mins/60)+' h '+(mins%60)+' min).';}
function timeToMinutes(value){const p=value.split(':').map(Number);return p[0]*60+p[1];}
