async function saveIncident(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus');b.disabled=true;try{const type=$('incident_type').value,planned=$('planned_time')?.value||null,start=$('incident_time').value,end=$('end_time')?.value||null;let duration=0;if(type==='Impuntualidad'){if(!planned||!start)throw Error('Indica la hora prevista y la hora real de entrada.');duration=Math.max(0,timeToMinutes(start)-timeToMinutes(planned));}else{if(!start||!end)throw Error('Indica la hora de inicio y la hora de reincorporación.');duration=timeToMinutes(end)-timeToMinutes(start);if(duration<0)duration+=1440;}await insert('incident_records',{worker_id:$('worker_id').value,incident_type:type,incident_date:$('incident_date').value,incident_time:start,planned_time:planned,end_time:end,duration_minutes:duration,is_justified:$('is_justified').checked,counts_for_bonus:$('counts_for_bonus').checked,notes:$('notes').value||null});closeModal();await loadAll();toast('Incidencia registrada ('+duration+' minutos).');}catch(err){s.textContent=err.message;b.disabled=false;}}
