async function savePartnerLink(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus'),id=window.linkingPartnerId;b.disabled=true;try{const employee=state.workers.find(x=>x.id===$('employee_worker_id').value),worker=state.workers.find(x=>x.id===$('referred_worker_id').value),partner=state.partners.find(x=>x.id===id);if(!employee||!worker||!partner||!workerVisible(employee.id)||!workerVisible(worker.id))throw Error('Busca y selecciona el empleado referente y la persona referida.');if(employee.id===worker.id)throw Error('El empleado y la persona referida deben ser distintos.');if(state.partners.some(p=>p.id!==id&&p.referred_worker_id===worker.id&&p.status!=='Cancelado'))throw Error('Ya existe otro Partner asociado a esa persona.');const {error}=await client().from('partner_records').update({employee_worker_id:employee.id,referrer_name:employee.agent,referred_worker_id:worker.id,referred_name:worker.agent,incentive:100}).eq('id',id);if(error)throw error;closeModal();await loadAll();toast('Vínculos Partner actualizados.');}catch(err){s.textContent=err.message;b.disabled=false;}}
