async function saveHours(e){e.preventDefault();const b=$('saveBtn'),s=$('formStatus');b.disabled=true;try{const workerId=$('worker_id').value,date=$('work_date').value,hours=Number($('hours').value);if(!workerId)throw Error('Busca y selecciona un trabajador.');if(!date||!Number.isFinite(hours)||hours<=0)throw Error('Indica una fecha y un número de horas válido.');await insert('extra_hours',{worker_id:workerId,work_date:date,concept:$('concept').value.trim()||'Horas extra',hours,amount:$('amount').value===''?null:Number($('amount').value),status:'Pendiente',notes:$('notes').value||null});closeModal();await loadAll();toast('Horas extra registradas.');}catch(err){s.textContent=err.message;b.disabled=false;}}
function showHoursImport(){modal('Importar horas extra','<p>El archivo debe incluir agente, sociedad, fecha y horas. Las filas que coincidan con la plantilla se registran automáticamente al seleccionar el Excel.</p><div class="notice">El importe y el concepto son opcionales. Los duplicados se omiten. Se mostrarán las filas que requieran corregir un trabajador, fecha u horas.</div><div class="field"><label>Archivo Excel o CSV</label><input id="hoursExcel" type="file" accept=".xlsx,.xls,.csv"></div><div id="hoursImportStatus" class="notice">Selecciona el archivo para empezar.</div><div id="hoursImportPreview"></div>');$('hoursExcel').addEventListener('change',importHoursExcel);}
function hoursNumber(value){if(typeof value==='number')return Number.isFinite(value)?value:null;const text=String(value??'').trim().replace(/\s/g,'').replace(/h$/i,'').replace(',','.');if(!text)return null;const number=Number(text);return Number.isFinite(number)?number:null;}
function hoursSheet(wb){const aliases={agent:['AGENTE','TRABAJADOR','EMPLEADO','NOMBRE','NOMBRE Y APELLIDOS'],company:['SOCIEDAD','EMPRESA','COMPANY'],work_date:['FECHA','FECHA TRABAJO','FECHA DE TRABAJO','DIA'],hours:['HORAS','HORAS EXTRA','HORA EXTRA','HOURS'],concept:['CONCEPTO','ACTIVIDAD'],amount:['IMPORTE','IMPORTE €','AMOUNT']};let best=null;for(const name of wb.SheetNames){const rows=XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:'',raw:true});for(let i=0;i<Math.min(rows.length,30);i++){const map={};Object.keys(aliases).forEach(k=>map[k]=findHeader((rows[i]||[]).map(String),aliases[k]));const score=['agent','company','work_date','hours'].filter(k=>map[k]>=0).length;if(score===4&&(!best||i<best.headerAt))best={name,rows,headerAt:i,map};}}return best;}
function hoursWorker(agent,company){const society=normalizeCompany(company)||company,targets=state.workers.filter(w=>norm(w.agent)===norm(agent)&&norm(w.company)===norm(society));return targets.length===1?targets[0]:null;}
function importKeyForHours(row){return [row.worker_id,row.work_date,row.hours,row.amount??'',norm(row.concept||'Horas extra')].join('|');}
async function importHoursExcel(event){const file=event.target.files?.[0],status=$('hoursImportStatus'),preview=$('hoursImportPreview');if(!file)return;status.textContent='Leyendo el archivo…';preview.innerHTML='';try{if(!window.XLSX)throw Error('No se ha cargado el lector Excel. Recarga la página con Ctrl+F5.');const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true,raw:true}),found=hoursSheet(wb);if(!found)throw Error('No encuentro una hoja con las columnas Agente, Sociedad, Fecha y Horas.');const {rows,headerAt,map}=found,parsed=rows.slice(headerAt+1).filter(row=>row.some(v=>String(v??'').trim())).map((row,index)=>{const agent=String(row[map.agent]??'').trim(),company=String(row[map.company]??'').trim(),date=excelDate(row[map.work_date]),hours=hoursNumber(row[map.hours]),amount=map.amount>=0&&String(row[map.amount]??'').trim()!==''?hoursNumber(row[map.amount]):null,concept=map.concept>=0?String(row[map.concept]??'').trim():'',worker=hoursWorker(agent,company),errors=[];if(!worker)errors.push('Trabajador no encontrado o nombre ambiguo');if(!date||date==='INVALID')errors.push('Fecha no válida');if(!hours||hours<=0)errors.push('Horas no válidas');if(amount!==null&&amount<0)errors.push('Importe no válido');const record=worker&&date&&date!=='INVALID'&&hours>0?{worker_id:worker.id,work_date:date,concept:concept||'Horas extra',hours,amount,status:'Pendiente',import_source:true,notes:'Importado desde '+file.name}:null;return {agent,company,date,hours,amount,record,errors,row:headerAt+index+2};});if(!parsed.length)throw Error('El archivo no contiene filas de horas extra.');const existingKeys=new Set(state.hours.map(x=>x.import_key).filter(Boolean)),seen=new Set();for(const item of parsed){if(item.record&&!item.errors.length){item.importKey=importKeyForHours(item.record);if(existingKeys.has(item.importKey)||seen.has(item.importKey)){item.duplicate=true;item.errors.push('Duplicado; omitido');}seen.add(item.importKey);}}const valid=parsed.filter(x=>x.record&&!x.errors.length);preview.innerHTML='<div class="card tablewrap" style="max-height:320px;overflow:auto"><table class="table"><thead><tr><th>Agente</th><th>Sociedad</th><th>Fecha</th><th>Horas</th><th>Importe</th><th>Resultado</th></tr></thead><tbody>'+parsed.slice(0,250).map(x=>'<tr><td>'+esc(x.agent||'—')+'</td><td>'+esc(x.company||'—')+'</td><td>'+esc(x.date||'—')+'</td><td>'+esc(x.hours??'—')+'</td><td>'+(x.amount===null?'—':money(x.amount))+'</td><td><span class="pill '+(x.errors.length?(x.duplicate?'amber':'red'):'green')+'">'+esc(x.errors.join(', ')||'Listo')+'</span></td></tr>').join('')+'</tbody></table></div><small>Hoja: '+esc(found.name)+' · '+parsed.length+' filas.</small>';if(!valid.length){status.textContent='No hay filas nuevas válidas para importar. Revisa los avisos de la vista previa.';return;}status.textContent='Registrando automáticamente '+valid.length+' filas…';const records=valid.map(x=>({...x.record,import_key:x.importKey}));let added=0,failures=[];for(let i=0;i<records.length;i+=25){const batch=records.slice(i,i+25),{error}=await client().from('extra_hours').insert(batch);if(!error){added+=batch.length;continue;}for(const record of batch){const {error:rowError}=await client().from('extra_hours').insert(record);if(rowError){if(rowError.code==='23505')continue;failures.push(record.work_date+': '+rowError.message);}else added++;}}await loadAll();status.textContent=failures.length?'Importación parcial: '+added+' filas registradas y '+failures.length+' con error. '+failures[0]:'Importación completada: '+added+' filas registradas automáticamente.';if(parsed.some(x=>x.errors.length&&!x.duplicate))status.textContent+=' Revisa las filas marcadas en rojo.';}catch(error){status.textContent='No se pudo importar el archivo: '+error.message;}}
