function showLeaveDetails(id){const x=state.leaves.find(item=>item.id===id);if(!x)return;const rows=[['Trabajador',workerName(x.worker_id)],['Tipo de permiso o ausencia',x.leave_type],['Categoría',x.category],['Desde',fmt(x.start_date)],['Hasta',fmt(x.end_date)],['Horas',x.hours_count==null?'—':x.hours_count+' h'],['Días',x.days_count==null?'—':x.days_count],['Permiso retribuido',x.is_paid||norm(x.category)==='retribuido'?'Sí':'No'],['Justificado',x.is_justified?'Sí':'No'],['Cuenta para el bono',x.counts_for_bonus?'Sí':'No'],['Observaciones',x.notes||'Sin observaciones']];modal('Ficha del permiso o ausencia', '<div class="profile-grid">'+rows.map(([label,value])=>'<div class="detailrow"><b>'+esc(label)+'</b><span>'+esc(value)+'</span></div>').join('')+'</div>');}
function renderIncidents(){const filtered=state.incidents.filter(x=>workerVisible(x.worker_id)&&inRange(x.incident_date,'incidents')),rows=filtered.map(x=>'<tr><td>'+esc(workerName(x.worker_id))+'</td><td>'+esc(x.incident_type)+'</td><td>'+fmt(x.incident_date)+'</td><td>'+esc(x.incident_time||'—')+'</td><td>'+x.duration_minutes+' min</td><td>'+esc(x.notes||'—')+'</td><td>'+esc(x.is_justified?'Justificada':'No justificada')+'</td><td>'+actionDelete('incident_records',x.id)+'</td></tr>');const weeks={};filtered.forEach(x=>{const d=new Date(x.incident_date+'T12:00:00'),monday=new Date(d);monday.setDate(d.getDate()-((d.getDay()+6)%7));const k=monday.toLocaleDateString('es-ES');weeks[k]=(weeks[k]||0)+1;});return '<div class="grid stats">'+Object.keys(weeks).map(k=>stat('Semana '+k,weeks[k],'Incidencias')).join('')+'</div>'+table(['Trabajador','Incidencia','Fecha','Hora','Duración','Observaciones','Estado','Acciones'],rows,'Todavía no hay incidencias en esta vista.');}
