function nextMonthEnd(date=today()){const d=new Date(date+'T12:00:00');return isoDate(new Date(d.getFullYear(),d.getMonth()+2,0));}
function extraHourStatus(item){const pending=state.pending.find(x=>x.source_extra_hours_id===item.id);if(pending)return pending.status==='Abonado'?'Abonado':'Pendiente';if(item.status==='Abonado')return 'Abonado';const month=item.work_date.slice(0,7),current=today().slice(0,7);return month>current?'Próximo':month===current?'Pendiente':'Abonado';}
async function recoverExtraHours(id){const item=state.hours.find(x=>x.id===id);if(!item||extraHourStatus(item)!=='Abonado'||state.pending.some(x=>x.source_extra_hours_id===id))return;try{const {error}=await client().from('pending_payments').insert({worker_id:item.worker_id,concept:'Horas extra · '+item.hours+' h · '+fmt(item.work_date),amount:item.amount,expected_date:nextMonthEnd(),status:'Pendiente',source_extra_hours_id:item.id,notes:'Recuperado desde Horas extra.'});if(error&&error.code!=='23505')throw error;await loadAll();toast('Horas extra enviadas a Pagos pendientes.');}catch(error){toast('No se pudo recuperar el pago: '+error.message);}}
function renderHours(){return table(['Trabajador','Fecha','Concepto','Horas','Importe','Estado','Acciones'],state.hours.filter(x=>workerVisible(x.worker_id)&&inRange(x.work_date,'hours')).map(x=>{const status=extraHourStatus(x),pending=state.pending.some(p=>p.source_extra_hours_id===x.id),action=status==='Abonado'&&!pending?'<button class="btn" onclick="recoverExtraHours(\''+x.id+'\')">Recuperar</button>':pending?'<span class="muted">En Pendientes</span>':'';return '<tr><td>'+esc(workerName(x.worker_id))+'</td><td>'+fmt(x.work_date)+'</td><td>'+esc(x.concept)+'</td><td>'+x.hours+'</td><td>'+(x.amount===null?'—':money(x.amount))+'</td><td><span class="pill '+(status==='Abonado'?'blue':status==='Pendiente'?'amber':'gray')+'">'+status+'</span></td><td>'+action+actionDelete('extra_hours',x.id)+'</td></tr>'; }),'Todavía no hay horas extra en esta vista.');}
function obligationMonthEnd(month){const d=new Date(month+'T12:00:00');return isoDate(new Date(d.getFullYear(),d.getMonth()+1,0));}
function obligationPending(item){return state.pending.find(p=>p.source_obligation_id===item.id);}
function obligationStatus(item){if(item.status==='No corresponde')return 'No corresponde';const pending=obligationPending(item);if(pending)return pending.status==='Abonado'?'Abonado':'Pendiente';if(item.status==='Abonado')return 'Abonado';const current=today().slice(0,7),month=item.payroll_month.slice(0,7);return month>current?'Próximo':month===current?'Pendiente':'Pasado';}
async function markObligationPending(id){const item=state.obligations.find(x=>x.id===id);if(!item||obligationStatus(item)!=='Pasado'||obligationPending(item))return;const concept=item.obligation_type==='Formación'?'Pago de formación':'Incentivo Partner';try{const {error}=await client().from('pending_payments').insert({worker_id:item.worker_id,concept,amount:item.amount,expected_date:nextMonthEnd(),status:'Pendiente',source_obligation_id:item.id,notes:'Recuperado desde Pagos adicionales.'});if(error&&error.code!=='23505')throw error;await loadAll();toast('Pago enviado a la ventana de Pendientes.');}catch(error){toast('No se pudo trasladar el pago: '+error.message);}}
function renderPayments(){const f=state.filters.payments||{},within=d=>(!f.from||d>=f.from)&&(!f.to||d<=f.to),monthWithin=d=>{const month=d.slice(0,7),end=obligationMonthEnd(d);return (!f.from||end>=f.from)&&(!f.to||month+'-01'<=f.to);},regular=state.payments.filter(x=>workerVisible(x.worker_id)&&within(x.payment_date)).map(x=>'<tr><td>'+esc(workerName(x.worker_id))+'</td><td>'+esc(x.concept)+'</td><td>'+esc(x.reference||'—')+'</td><td>'+money(x.amount)+'</td><td>'+fmt(x.payment_date)+'</td><td><span class="pill '+(x.status==='Abonado'?'blue':'amber')+'">'+esc(x.status)+'</span></td><td>'+actionDelete('additional_payments',x.id)+'</td></tr>'),auto=state.obligations.filter(x=>workerVisible(x.worker_id)&&monthWithin(x.payroll_month)).map(x=>{const status=obligationStatus(x),concept=x.obligation_type==='Formación'?'Pago de formación':'Incentivo Partner',pending=obligationPending(x),action=status==='Pasado'&&!pending?'<button class="btn primary" onclick="markObligationPending(\''+x.id+'\')">Marcar como pendiente</button>':pending?'<span class="muted">En Pendientes</span>':'';return '<tr><td>'+esc(workerName(x.worker_id))+'</td><td>'+concept+'</td><td>'+(x.partner_record_id?'Partner referido':'Nómina')+'</td><td>'+(x.amount===null?'—':money(x.amount))+'</td><td>'+fmt(obligationMonthEnd(x.payroll_month))+'</td><td><span class="pill '+(status==='Abonado'?'blue':status==='No corresponde'?'gray':status==='Pasado'?'red':status==='Próximo'?'gray':'amber')+'">'+status+'</span></td><td>'+action+'</td></tr>';});const rows=auto.concat(regular);return '<div class="notice">Formación aparece sin importe y Partner por 100 €. Ambos se prevén al cierre del primer mes natural completo, si la persona sigue activa hasta ese día. Los pagos que pasan sin realizarse se pueden enviar a Pendientes.</div>'+table(['Trabajador','Concepto','Origen','Importe','Fecha prevista','Estado','Acciones'],rows,'No hay pagos adicionales ni conceptos previstos en el periodo.');}
function renderPending(){const rows=state.pending.filter(x=>workerVisible(x.worker_id)&&inRange(x.expected_date,'pending')).map(x=>{const age=Math.max(0,Math.floor((new Date(today())-new Date(x.expected_date))/86400000));return '<tr><td>'+esc(workerName(x.worker_id))+'</td><td>'+esc(x.concept)+'</td><td>'+(x.amount===null?'—':money(x.amount))+'</td><td>'+fmt(x.expected_date)+'</td><td>'+age+' días</td><td>'+esc(x.status)+'</td><td>'+(x.status==='Pendiente'?'<button class="btn primary" onclick="markPaid(\''+x.id+'\')">Marcar abonado</button> ':'')+actionDelete('pending_payments',x.id)+'</td></tr>';});const visible=state.pending.filter(x=>workerVisible(x.worker_id)),total=visible.filter(x=>x.status==='Pendiente').reduce((s,x)=>s+(Number(x.amount)||0),0);return '<div class="grid stats">'+stat('Importe pendiente',money(total),'Total cuantificado sin abonar')+stat('Registros pendientes',visible.filter(x=>x.status==='Pendiente').length,'Pagos abiertos')+'</div>'+table(['Trabajador','Concepto','Importe','Fecha prevista','Antigüedad','Estado','Acciones'],rows,'No hay pagos pendientes en esta vista.');}
function countedAbsenceDates(workerId){const intervals=[];for(const x of state.leaves){if(x.worker_id!==workerId||!x.counts_for_bonus||x.is_paid||norm(x.category)==='retribuido')continue;intervals.push([calendarDayIndex(x.start_date),calendarDayIndex(x.end_date)]);}for(const x of state.incidents){if(x.worker_id!==workerId||!x.counts_for_bonus)continue;const day=calendarDayIndex(x.incident_date);intervals.push([day,day]);}intervals.sort((a,b)=>a[0]-b[0]);let total=0,start=null,end=null;for(const [a,b] of intervals){if(start===null){start=a;end=b;}else if(a<=end+1){end=Math.max(end,b);}else{total+=end-start+1;start=a;end=b;}}if(start!==null)total+=end-start+1;return total;}
function bonusAbsences(workerId){return countedAbsenceDates(workerId);}
function bonusRecovery(workerId,year=new Date().getFullYear()){return state.bonusRecoveries.find(x=>x.worker_id===workerId&&Number(x.bonus_year)===Number(year));}
async function recoverBonus(workerId){const year=new Date().getFullYear();if(bonusAbsences(workerId)<3||bonusRecovery(workerId,year))return;const {error}=await client().from('bonus_recoveries').insert({worker_id:workerId,bonus_year:year,notes:'Recuperación autorizada manualmente.'});if(error&&error.code!=='23505'){toast('No se pudo recuperar el bono: '+error.message);return;}await loadAll();toast('Bono recuperado. La persona vuelve a tener derecho.');}
function lostBonusWorkers(){const year=new Date().getFullYear();return visibleWorkers().filter(w=>bonusAbsences(w.id)>=3&&!bonusRecovery(w.id,year));}
async function recoverLostBonus(workerId){await recoverBonus(workerId);showLostBonusWorkers();}
function showLostBonusWorkers(){const rows=lostBonusWorkers().map(w=>'<tr><td>'+esc(w.agent)+'</td><td>'+esc(w.company)+'</td><td>'+bonusAbsences(w.id)+'</td><td><button class="btn" onclick="bonusDetails(\''+w.id+'\')">Ver detalle</button> <button class="btn primary" onclick="recoverLostBonus(\''+w.id+'\')">Recuperar bono</button></td></tr>');modal('Personas con el bono perdido',table(['Trabajador','Sociedad','Días computables','Acciones'],rows,'No hay personas con el bono perdido en la plantilla visible.'));}
function renderBonuses(){const year=new Date().getFullYear(),rows=visibleWorkers().map(w=>{const absences=bonusAbsences(w.id),recovered=!!bonusRecovery(w.id,year),lost=absences>=3&&!recovered,entitled=!lost;return '<tr><td>'+esc(w.agent)+'</td><td>'+absences+'</td><td>'+money(entitled?200:0)+'</td><td><span class="pill '+(entitled?'green':'red')+'">'+(entitled?'Con derecho':'Perdido')+'</span></td><td><button class="btn" onclick="bonusDetails(\''+w.id+'\')">Ver detalle</button>'+(lost?'<button class="btn primary" onclick="recoverBonus(\''+w.id+'\')">Recuperar bono</button>':recovered?' <span class="muted">Recuperado</span>':'')+'</td></tr>';});const lost=lostBonusWorkers().length;return '<div class="grid stats">'+stat('Importe del bono','200 €','Por trabajador')+stat('Umbral de ausencias','3','Ausencias computables')+stat('Bonos perdidos',lost,'Pulsa para ver las personas','showLostBonusWorkers()')+'</div>'+table(['Trabajador','Ausencias computables','Importe','Estado del bono','Acciones'],rows,'Todavía no hay trabajadores registrados.')+'<div class="notice">El bono se considera por defecto. Las ausencias computables pueden hacer que se pierda al llegar a 3. Si se autoriza una excepción, usa Recuperar bono; la persona volverá a figurar con derecho. Este apartado controla el derecho, no registra el abono.</div>';}
function bonusDetails(id){const items=state.leaves.filter(x=>x.worker_id===id&&x.counts_for_bonus&&!x.is_paid&&norm(x.category)!=='retribuido').map(x=>'<div class="detailrow">'+esc(x.leave_type)+' · '+fmt(x.start_date)+'–'+fmt(x.end_date)+' · '+calendarDaysBetween(x.start_date,x.end_date)+' días</div>').concat(state.incidents.filter(x=>x.worker_id===id&&x.counts_for_bonus).map(x=>'<div class="detailrow">'+esc(x.incident_type)+' · '+fmt(x.incident_date)+' · 1 día computable</div>'));modal('Detalle del bono · '+workerName(id),'<div class="notice">Días computables sin duplicar fechas: <b>'+bonusAbsences(id)+'</b></div>'+(items.join('')||'<p>No hay ausencias computables.</p>'));}
const reportFieldLabels={date:'Fecha',area:'Área',person:'Persona',concept:'Concepto',detail:'Detalle',amount:'Importe',status:'Estado'};
function analysisRows(){const q=state.analysis,from=q.from||isoDate(new Date(new Date().getFullYear(),new Date().getMonth(),1)),to=q.to||today(),area=q.area||'all',society=q.society||'',rows=[];const inDates=(d,end=d)=>end>=from&&d<=to;const companyFor=id=>state.workers.find(w=>w.id===id)?.company||'';const add=(r)=>{if(!inDates(r.date,r.endDate||r.date))return;if(society&&companyFor(r.workerId)!==society)return;if(area!=='all'&&area!==r.area)return;rows.push(r);};
 for(const w of state.workers){if(inDates(w.hire_date))add({date:w.hire_date,area:'workers',workerId:w.id,person:w.agent,concept:'Alta de trabajador',detail:w.company,amount:null,status:'Registrado'});if(w.termination_date&&inDates(w.termination_date))add({date:w.termination_date,area:'workers',workerId:w.id,person:w.agent,concept:'Baja de trabajador',detail:w.termination_reason||'—',amount:null,status:'Registrado'});}
 for(const x of state.vacations)add({date:x.start_date,endDate:x.end_date,area:'vacations',workerId:x.worker_id,person:workerName(x.worker_id),concept:x.kind==='week'?'Vacaciones · semana':'Vacaciones · días sueltos',detail:fmt(x.start_date)+'–'+fmt(x.end_date)+' · '+x.days_count+' días',amount:null,status:'Registrado'});
 for(const x of state.leaves)add({date:x.start_date,endDate:x.end_date,area:'leaves',workerId:x.worker_id,person:workerName(x.worker_id),concept:x.leave_type,detail:x.hours_count?x.hours_count+' horas':x.days_count+' días',amount:null,status:x.is_paid?'Retribuido':x.is_justified?'Justificado':'Injustificado'});
 for(const x of state.incidents)add({date:x.incident_date,area:'leaves',workerId:x.worker_id,person:workerName(x.worker_id),concept:x.incident_type,detail:x.duration_minutes+' min · '+(x.notes||'—'),amount:null,status:x.is_justified?'Justificada':'No justificada'});
 for(const x of state.partners)add({date:x.incorporation_date,area:'partners',workerId:x.referred_worker_id,person:x.referred_name,concept:'Alta de Partner',detail:'Referente: '+x.referrer_name+' · incentivo previsto al primer mes completo',amount:null,status:x.status});
 for(const x of state.hours)add({date:x.work_date,area:'hours',workerId:x.worker_id,person:workerName(x.worker_id),concept:x.concept,detail:x.hours+' horas',amount:Number(x.amount||0),status:x.status});
 for(const x of state.payments)add({date:x.payment_date,area:'payments',workerId:x.worker_id,person:workerName(x.worker_id),concept:x.concept,detail:x.reference||'—',amount:Number(x.amount||0),status:x.status});
 for(const x of state.pending)add({date:x.expected_date,area:'pending',workerId:x.worker_id,person:workerName(x.worker_id),concept:x.concept,detail:'Fecha prevista de abono',amount:Number(x.amount||0),status:x.status});
 for(const x of state.obligations){const status=obligationStatus(x);if(status==='No corresponde')continue;const person=workerName(x.worker_id),concept=x.obligation_type==='Formación'?'Pago de formación':'Incentivo Partner';add({date:x.payroll_month,area:'payments',workerId:x.worker_id,person,concept,detail:x.obligation_type==='Formación'?'Corresponde en la primera nómina mensual completa':'Incentivo Partner · primer mes de nómina completa',amount:x.amount===null?null:Number(x.amount),status});}
 return rows.sort((a,b)=>a.date.localeCompare(b.date)||a.person.localeCompare(b.person,'es'));
}
function analysisForm(){if(!state.analysis.from)state.analysis.from=isoDate(new Date(new Date().getFullYear(),new Date().getMonth(),1));if(!state.analysis.to)state.analysis.to=today();const societyOptions='<option value="">Todas las sociedades</option>'+state.societies.map(s=>'<option value="'+esc(s.name)+'" '+(state.analysis.society===s.name?'selected':'')+'>'+esc(s.name)+'</option>').join(''),areas=[['all','Todo el sistema'],['workers','Trabajadores'],['vacations','Vacaciones'],['leaves','Permisos e incidencias'],['partners','Partners'],['hours','Horas extra'],['payments','Pagos adicionales'],['pending','Pagos pendientes']];const selected=state.analysis.fields||Object.keys(reportFieldLabels);const fields=Object.entries(reportFieldLabels).map(([key,label])=>'<label class="report-field"><input type="checkbox" name="reportField" value="'+key+'" '+(selected.includes(key)?'checked':'')+'> '+label+'</label>').join('');return '<form id="analysisForm" class="analysis-filters"><div class="field"><label for="analysisFrom">Desde</label><input id="analysisFrom" type="date" value="'+state.analysis.from+'" required></div><div class="field"><label for="analysisTo">Hasta</label><input id="analysisTo" type="date" value="'+state.analysis.to+'" required></div><div class="field"><label for="analysisArea">Área</label><select id="analysisArea">'+areas.map(([key,label])=>'<option value="'+key+'" '+((state.analysis.area||'all')===key?'selected':'')+'>'+label+'</option>').join('')+'</select></div><div class="field"><label for="analysisSociety">Sociedad</label><select id="analysisSociety">'+societyOptions+'</select></div><details class="report-fields"><summary>Elegir campos del informe</summary><div class="report-field-list">'+fields+'</div></details><button class="btn" type="submit">'+icon('check')+'Aplicar filtros</button><button class="btn primary" type="button" onclick="exportAnalysisPdf()">'+icon('download')+'Exportar PDF</button></form>';}
function renderAnalysis(){if(!state.analysis.from)state.analysis.from=isoDate(new Date(new Date().getFullYear(),new Date().getMonth(),1));if(!state.analysis.to)state.analysis.to=today();const rows=analysisRows(),fields=state.analysis.fields||Object.keys(reportFieldLabels),areaLabels={all:'Todo el sistema',workers:'Trabajadores',vacations:'Vacaciones',leaves:'Permisos e incidencias',partners:'Partners',hours:'Horas extra',payments:'Pagos adicionales',pending:'Pagos pendientes'},amount=rows.reduce((s,x)=>s+(x.amount===null?0:Number(x.amount)||0),0),columns=fields.map(k=>'<th>'+reportFieldLabels[k]+'</th>').join(''),body=rows.length?rows.map(r=>'<tr>'+fields.map(k=>'<td>'+esc(k==='date'?fmt(r.date):k==='area'?areaLabels[r.area]:k==='person'?r.person:k==='concept'?r.concept:k==='detail'?r.detail:k==='amount'?r.amount===null?'—':money(r.amount):r.status)+'</td>').join('')+'</tr>').join(''):'<tr><td class="empty-state" colspan="'+Math.max(fields.length,1)+'"><div class="empty-icon">'+icon('file')+'</div><strong>No hay datos en el intervalo elegido.</strong></td></tr>';const from=state.analysis.from,to=state.analysis.to,society=state.analysis.society||'Todas las sociedades';return header('INFORMES','Análisis','Filtra los registros de Acerca y prepara un informe en PDF.','')+analysisForm()+'<div class="grid stats analysis-stats">'+stat('Registros incluidos',rows.length,'Con los filtros aplicados')+stat('Importes cuantificados',money(amount),'Los conceptos sin cuantía no se suman')+stat('Área',areaLabels[state.analysis.area||'all'],society)+'</div><div class="card tablewrap analysis-table"><table class="table"><thead><tr>'+columns+'</tr></thead><tbody>'+body+'</tbody></table></div><div id="printReport" class="print-report"><div class="print-brand">ACERCA · GESTIÓN INTERNA</div><h1>Informe de análisis</h1><p>Periodo: '+fmt(from)+' – '+fmt(to)+' · Área: '+esc(areaLabels[state.analysis.area||'all'])+' · Sociedad: '+esc(society)+'</p><p>'+rows.length+' registros · Importe cuantificado: '+money(amount)+'</p><table><thead><tr>'+columns+'</tr></thead><tbody>'+body+'</tbody></table><footer>Informe generado el '+fmt(today())+' · Uso interno ACERCA</footer></div>';}
function collectAnalysisFilters(){const from=$('analysisFrom').value,to=$('analysisTo').value;if(!from||!to||from>to){toast('Comprueba el intervalo de fechas.');return false;}const fields=[...document.querySelectorAll('#analysisForm [name="reportField"]:checked')].map(x=>x.value);if(!fields.length){toast('Selecciona al menos un campo para el informe.');return false;}state.analysis={from,to,area:$('analysisArea').value,society:$('analysisSociety').value,fields};return true;}
function applyAnalysisFilters(event){event.preventDefault();if(collectAnalysisFilters())render();}
function exportAnalysisPdf(){if($('analysisForm')&&!collectAnalysisFilters())return;render();window.print();}
function nextWeek(){const d=new Date();d.setHours(12,0,0,0);const delta=7-((d.getDay()+6)%7);d.setDate(d.getDate()+delta);const start=isoDate(d);d.setDate(d.getDate()+6);return {start,end:isoDate(d)};}
function showUpcomingVacations(){const range=nextWeek(),rows=state.vacations.filter(v=>v.start_date<=range.end&&v.end_date>=range.start).map(v=>'<tr><td>'+esc(workerName(v.worker_id))+'</td><td>'+esc(state.workers.find(w=>w.id===v.worker_id)?.company||'—')+'</td><td>'+fmt(v.start_date)+'</td><td>'+fmt(v.end_date)+'</td></tr>');modal('Vacaciones próximas · '+fmt(range.start)+'–'+fmt(range.end),table(['Trabajador','Sociedad','Desde','Hasta'],rows,'No hay vacaciones en la semana siguiente.'));}
function renderHome(){const active=state.workers.filter(w=>!w.termination_date||w.termination_date>=today()).length,pending=state.pending.filter(x=>x.status==='Pendiente').reduce((s,x)=>s+Number(x.amount),0),range=nextWeek(),upcomingWorkers=new Set(state.vacations.filter(v=>workerVisible(v.worker_id)&&v.start_date<=range.end&&v.end_date>=range.start).map(v=>v.worker_id)).size,month=today().slice(0,7),obligations=state.obligations.filter(x=>x.payroll_month.slice(0,7)===month&&obligationStatus(x)!=='Abonado'&&obligationStatus(x)!=='No corresponde').length;return header('RESUMEN GENERAL','Bienvenido a Acerca','Resumen actualizado de la gestión interna.','<button class="btn" onclick="go(\'analisis\')">'+icon('file')+' Abrir análisis</button>')+'<div class="grid stats">'+stat('Trabajadores activos',active,'En plantilla')+stat('Vacaciones próximas',upcomingWorkers,fmt(range.start)+'–'+fmt(range.end),'showUpcomingVacations()')+stat('Incidencias este mes',state.incidents.filter(x=>x.incident_date.slice(0,7)===today().slice(0,7)).length,'Impuntualidades y abandonos')+stat('Pagos pendientes',money(pending),'Importe por abonar')+'</div>'+(obligations?'<div class="card wide"><div><b>Pagos de nómina previstos</b><small>'+obligations+' conceptos automáticos corresponden este mes. Consulta la previsión y el informe completo.</small></div><button class="btn primary" onclick="go(\'pagos\')">Ver pagos adicionales</button></div>':'');}
function renderConfig(){const rows=state.societies.map(x=>'<div class="detailrow"><span>'+esc(x.name)+(x.active?'':' · Inactiva')+'</span><span class="actions"><button class="btn" data-society-action="edit" data-society-name="'+esc(x.name)+'">Editar</button><button class="btn" data-society-action="toggle" data-society-name="'+esc(x.name)+'">'+(x.active?'Desactivar':'Activar')+'</button></span></div>').join('');return header('SISTEMA','Configuración','Gestiona el catálogo de sociedades.')+'<div class="card panel"><div class="head"><div><h3>Sociedades</h3><p>Las sociedades con trabajadores asociados se conservan en el historial.</p></div><button class="btn primary" onclick="showSocietyForm()">'+icon('plus')+' Añadir sociedad</button></div>'+(rows||'<p>Todavía no hay sociedades configuradas.</p>')+'</div>'+(state.societies.length?'':'<div class="notice">Configura al menos una sociedad antes de crear o importar trabajadores.</div>');}
function render(){
 $('crumb').textContent=titles[state.page];const navGroup=['trabajadores','vacaciones','permisos','incidencias'].includes(state.page)?'personas':['partners','horas','pagos','pendientes','bonos'].includes(state.page)?'pagos':state.page;document.querySelectorAll('#mainNav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.group?b.dataset.group===navGroup:b.dataset.page===state.page));
 $('workerStatusFilter').innerHTML=workerStatusControl();
 const v=$('view');let html='';
 switch(state.page){
 case 'inicio':html=renderHome();break;
 case 'trabajadores':html=header('PERSONAS','Trabajadores','Consulta y actualiza las fichas de la plantilla.','<button class="btn" onclick="showExcelImport()">Importar Excel</button><button class="btn primary" onclick="showNewWorker()">+ Nuevo trabajador</button>')+sectionNav('personas')+dateFilter('workers')+renderWorkers();break;
 case 'vacaciones':html=header('PERSONAS','Vacaciones','Consulta saldos, registra periodos y revisa el calendario.','<button class="btn primary" onclick="showVacationForm()">+ Registrar vacaciones</button>')+sectionNav('personas')+renderVacations();break;
 case 'permisos':html=header('PERSONAS','Permisos y ausencias','Gestiona permisos retribuidos, ausencias y bajas.','<button class="btn primary" onclick="showLeaveForm()">+ Nuevo registro</button>')+sectionNav('personas')+'<div class="grid stats">'+stat('Horas médicas',state.leaves.filter(x=>workerVisible(x.worker_id)&&x.leave_type==='Horas médicas').reduce((s,x)=>s+Number(x.hours_count||0),0)+' h','36 horas anuales de referencia')+stat('Fuerza mayor',state.leaves.filter(x=>workerVisible(x.worker_id)&&x.leave_type==='Fuerza mayor').reduce((s,x)=>s+Number(x.days_count||0),0)+' días','4 días anuales de referencia')+stat('Ausencias',state.leaves.filter(x=>workerVisible(x.worker_id)&&!x.is_paid).length,'No retribuidas')+'</div>'+dateFilter('leaves')+renderLeaves();break;
 case 'incidencias':html=header('PERSONAS','Incidencias','Control de impuntualidades y abandonos.','<button class="btn primary" onclick="showIncidentForm()">+ Registrar incidencia</button>')+sectionNav('personas')+dateFilter('incidents')+renderIncidents();break;
 case 'partners':html=header('PAGOS','Partners','Consulta referencias e incentivos previstos.','<button class="btn primary" onclick="showPartnerForm()">+ Registrar Partner</button>')+sectionNav('pagos')+dateFilter('partners')+renderPartners();break;
 case 'horas':html=header('PAGOS','Horas extra','Registra y revisa horas. Las horas de meses cerrados figuran como abonadas; puedes recuperarlas si no se pagaron.','<button class="btn" onclick="showHoursImport()">Importar Excel</button><button class="btn primary" onclick="showHoursForm()">+ Registrar horas</button>')+sectionNav('pagos')+dateFilter('hours')+renderHours();break;
 case 'pagos':html=header('PAGOS','Pagos adicionales','Consulta importes y pagos previstos por nómina.','<button class="btn primary" onclick="showPaymentForm()">+ Registrar pago</button>')+sectionNav('pagos')+dateFilter('payments')+renderPayments();break;
 case 'pendientes':html=header('PAGOS','Pendientes','Consulta y controla los importes pendientes.','<button class="btn primary" onclick="showPendingForm()">+ Registrar pendiente</button>')+sectionNav('pagos')+dateFilter('pending')+renderPending();break;
 case 'bonos':html=header('PAGOS','Bonos','Consulta el derecho al bono y recupera los casos autorizados.')+sectionNav('pagos')+renderBonuses();break;
 case 'analisis':html=renderAnalysis();break;
 case 'configuracion':html=renderConfig();break;
 }
 v.innerHTML=html;if(state.page==='trabajadores')v.querySelector('.toolbar.range')?.remove();if(state.page==='vacaciones'){const actions=v.querySelector('.head .actions');if(actions)actions.insertAdjacentHTML('afterbegin','<button class="btn" onclick="showVacationImport()">Importar Excel</button>');}
 v.querySelectorAll('[data-society-action]').forEach(button=>button.addEventListener('click',()=>button.dataset.societyAction==='edit'?showSocietyForm(button.dataset.societyName):toggleSociety(button.dataset.societyName)));
 const analysisFormElement=v.querySelector('#analysisForm');if(analysisFormElement)analysisFormElement.addEventListener('submit',applyAnalysisFilters);
}
