$('modalBody').addEventListener('click',e=>{const option=e.target.closest('[data-worker-id]'),field=option?.dataset.workerField;if(!field?.startsWith('vac_import_'))return;state.vacationImportRows.forEach((item,i)=>{const value=$('vac_import_'+i)?.value;if(value)item.worker_id=value;});const index=Number(field.slice('vac_import_'.length)),item=state.vacationImportRows[index];if(!item)return;item.worker_id=option.dataset.workerId;item.errors=item.errors.filter(error=>!error.startsWith('Trabajador no encontrado')&&!error.startsWith('Nombre coincidente'));item.record={worker_id:item.worker_id,start_date:item.start,end_date:item.end,kind:item.kind,days_count:item.days,notes:'Importado desde Excel'};const key=vacationImportKey(item.record);if(state.vacations.some(v=>vacationImportKey(v)===key)||state.vacationImportRows.some((other,i)=>i!==index&&other.worker_id===item.worker_id&&other.start===item.start&&other.end===item.end&&other.kind===item.kind)){item.duplicate=true;item.errors.push('Duplicado');}else if(state.vacations.some(v=>v.worker_id===item.worker_id&&v.start_date<=item.end&&v.end_date>=item.start))item.errors.push('Se solapa con otro periodo existente');vacationImportPreview();});
